window.STUDY_CARDS = [
// module, topic, level, source, front, back
["S1","风险管理","core","S1课程材料 · 风险管理","风险管理流程通常从什么开始？","界定任务、人员、设备和环境，识别可能造成伤害的危险源；之后评估风险、选择控制措施、记录并复核。"],
["S1","风险管理","core","S1课程材料 · 风险管理","hazard（危险源）与 risk（风险）有什么区别？","危险源是可能造成伤害或损害的来源；风险描述伤害发生的可能性及其后果。"],
["S1","风险管理","core","S1课程材料 · 风险管理","风险评估至少要考虑哪两个维度？","伤害后果的严重程度，以及发生的可能性；同时检查现有控制是否足够。"],
["S1","风险管理","detail","S1课程材料 · 风险管理","为什么任务风险评估要针对现场，而不能只套模板？","人员能力、设备状态、环境、能源来源和任务步骤会变化；模板可提示项目，但不能替代现场识别和判断。"],
["S1","风险管理","core","S1课程材料 · 风险管理","控制措施的优先级应如何思考？","先考虑消除危险，其次采用替代、隔离和工程控制，再考虑管理措施；PPE 是重要防线，但不能替代可行的高层级控制。"],
["S1","风险管理","detail","S1课程材料 · 风险管理","风险控制计划为什么要记录并在作业后复核？","记录便于沟通责任、控制措施和残余风险；作业后复核能发现控制是否有效以及现场是否出现新风险。"],
["S1","风险管理","detail","S1课程材料 · 风险管理","举例说明电气任务中的非电气危险。","搬运重物、噪声、粉尘、滑倒、热环境或狭窄空间都可能造成伤害，同样要纳入风险评估。"],
["S1","电气危险","core","原教材 Chapter 2 · 低压危险","低压设备为什么不能被视为“低风险”？","低压仍可造成致命电击、弧光灼伤和火灾；小间隙、多个电源、感应电压、残余电荷或中性线异常都会增加危险。"],
["S1","电气危险","core","原教材 Chapter 2 · 低压危险","课程材料给出的低压范围是什么？","课程材料按交流高于 50 V rms 且不超过 1000 V rms、直流高于 120 V 且不超过 1500 V 描述低压范围。记忆课程定义；实际分类与作业要求须以当前适用标准为准。"],
["S1","电气危险","detail","原教材 Chapter 2 · 低压危险","creepage distance（爬电距离）指什么？","沿绝缘材料表面测量的两个导电部分之间最短路径；不要与穿过空气的电气间隙混淆。"],
["S1","电气危险","detail","原教材 Chapter 2 · 低压危险","clearance（电气间隙）与爬电距离的区别是什么？","电气间隙是导电部分之间穿过空气的最短距离；爬电距离沿绝缘表面测量。"],
["S1","电气危险","core","原教材 Chapter 2 · 低压危险","教材强调的常见电气伤害类别有哪些？","电击、与电弧相关的灼伤/弧闪伤害，以及电弧产生的有害气体或烟雾。"],
["S1","电气危险","detail","S1课程材料 · 危险源识别","电容器隔离电源后为什么仍需谨慎？","电容器可能保留危险能量，也可能因电路状态再次充电；必须按授权程序放电并验证，不能仅凭断电判断安全。"],
["S1","电气危险","detail","S1课程材料 · 危险源识别","断开的中性线或闲置导体为何仍可能有危险电压？","可能受到多电源、错误接线、感应或其他回路影响；应把未验证的导体视为可能带电。"],
["S1","电气危险","detail","S1课程材料 · 危险源识别","多路供电为什么会破坏“已关主开关即无电”的假设？","备用电源、光伏/储能、联络回路或其他独立电源可能仍向局部设备供电，必须识别并隔离所有来源。"],
["S1","电气危险","core","S1课程材料 · 接地故障","step voltage（跨步电压）是什么？","故障电流在地面形成电位梯度时，两脚相隔一定步距所跨越的电位差。"],
["S1","电气危险","core","S1课程材料 · 接地故障","touch voltage（接触电压）如何形成？","人体同时接触不同电位的导电部分时，例如手触及故障带电外壳而脚站在较低电位地面，人体会承受电位差。"],
["S1","电气危险","detail","S1课程材料 · 接地故障","direct contact 与 indirect contact 有什么区别？","直接接触通常带电的部分；间接接触因故障而意外带电的可触及导电部分。"],
["S1","电气危险","detail","S1课程材料 · 保护原理","RCD 的保护作用是什么？","检测规定条件下的剩余电流并自动切断电源，可降低某些电击风险；它不能替代隔离、接地、正确保护或安全作业程序。"],
["S1","电气危险","detail","S1课程材料 · 保护原理","等电位联结的安全目标是什么？","降低可同时触及导电部分之间的电位差，从而减少触电风险；具体范围和做法须按设计及现行规范确定。"],
["S1","隔离与上锁","core","原教材 Chapter 2 · Isolation / LOTO","电气作业中 isolation（隔离）的目标是什么？","防止作业期间危险能源意外进入作业区域或设备；隔离对象要覆盖所有可能的电源和回馈路径。"],
["S1","隔离与上锁","core","原教材 Chapter 2 · Isolation / LOTO","安全隔离的学习顺序应包含哪些关键动作？","识别能源、通知受影响人员、停机、隔离、锁定并挂牌、处理残余能量、验证隔离有效；按现场授权程序执行。"],
["S1","隔离与上锁","core","原教材 Chapter 2 · Isolation / LOTO","为什么“试着启动设备”不能单独证明已安全隔离？","控制回路或机械机构可能故障，试启动也不能验证所有导体无电；须使用合适仪表按程序验证。"],
["S1","隔离与上锁","core","原教材 Chapter 2 · Isolation / LOTO","验证无电前后，测试仪表应怎样确认？","使用前确认仪表在已知电源上正常工作；完成无电验证后再次确认仪表仍正常，以排除仪表/表笔故障造成的假读数。"],
["S1","隔离与上锁","detail","原教材 Chapter 2 · Isolation / LOTO","个人危险标签和设备停用标签的目的有什么不同？","个人危险标签用于表明人员正在作业并禁止未经授权恢复能源；停用标签说明设备有故障或不适用。现场定义和流程遵从雇主程序。"],
["S1","隔离与上锁","detail","S1课程材料 · 残余能量","完成隔离后还要考虑哪些非电能量？","机械储能、弹簧/重力、气压、液压、热能、旋转惯性和电容储能等；需要按任务安全释放或约束。"],
["S1","测试与仪表","core","原教材 Chapter 2 · Test instruments","CAT I–IV 分类主要反映什么？","仪表在不同电气测量位置可能承受的瞬态过电压/故障能量环境；选择类别要同时匹配测量位置和电压额定值。"],
["S1","测试与仪表","detail","原教材 Chapter 2 · Test instruments","CAT III 与 CAT IV 测量环境大致如何区分？","CAT III 常对应建筑固定配电和设备回路；CAT IV 更靠近供电入口/源端、预期瞬态能量更高。按仪表和现行标准铭牌核对。"],
["S1","测试与仪表","core","原教材 Chapter 2 · IP ratings","IP 代码中的第一位和第二位分别表示什么？","第一位表示对固体异物及接近危险部件的防护等级；第二位表示防水等级。完整含义需查对应 IP 等级表。"],
["S1","测试与仪表","detail","S1课程材料 · 测试仪表","测试前为什么要检查表笔、探头和仪表额定值？","损坏或等级不匹配会导致读数错误、仪表失效或电击/弧闪危险；检查外观、功能和测量类别额定值。"],
["S1","弧闪与人体效应","core","S1课程材料 · 电击与弧闪","弧闪可能带来哪些伤害？","强热辐射、压力/飞散物、强光和紫外辐射、噪声及烟气伤害；危害取决于系统和故障条件。"],
["S1","弧闪与人体效应","detail","S1课程材料 · 电击与弧闪","预防弧闪最有效的基本策略是什么？","在可行且按授权程序的前提下，使设备处于安全去电状态，并正确隔离、锁定和验证；PPE 是剩余风险的防护层。"],
["S1","有害物质","core","原教材 Chapter 2 · Hazardous materials","发现疑似含石棉材料时，第一原则是什么？","停止可能扰动材料的工作，不自行钻、切、打磨或取样；隔离并按法规和雇主程序交由合格人员评估处理。"],
["S1","有害物质","detail","原教材 Chapter 2 · Hazardous materials","biosoluble（生物可溶）为何不等于无害？","表示材料可在体液中溶解并较快清除的特性，不代表吸入暴露没有风险；仍需控制粉尘并采用适当防护。"],
["S1","有害物质","detail","S1课程材料 · 粉尘与生物危害","硅尘和木尘作业应关注什么控制？","优先减少粉尘产生并采用适当局部抽排/湿式控制；呼吸防护、清理和废弃物处置按材料风险及现场程序选择。"],
["S1","有害物质","detail","S1课程材料 · 粉尘与生物危害","光纤作业的小玻璃碎屑为什么危险？","可能刺伤眼睛或皮肤，也可能被吸入/摄入；使用合适收集方法并放入规定的锐器容器，不能徒手清理。"],
["S1","现场安全","core","S1课程材料 · Construction work","风险控制层级里 PPE 为什么不能单独依赖？","PPE 只能降低佩戴者接触危害的程度，不能消除危险源；还依赖正确选择、适配、维护和持续佩戴。"],
["S1","现场安全","detail","S1课程材料 · Testing equipment","测试仪器的证明前后检查（prove-test-prove）有什么逻辑？","先证明仪表能工作，再测被测对象，最后再次证明仪表仍工作；若前后任一检查失败，测量结果不能作为可靠的无电证明。"],
["S1","风险管理","detail","S1课程材料 · Risk assessment","风险分析和风险控制分别解决什么问题？","风险分析判断伤害可能性、后果和风险等级；风险控制决定如何消除或降低风险，并检查措施是否有效。"],
["S1","风险管理","detail","S1课程材料 · Risk assessment","什么是 residual risk（残余风险）？","实施控制措施后仍然存在的风险；开工前应确认其是否可接受，以及是否需要进一步控制或停止任务。"],
["S1","电气危险","detail","S1课程材料 · Electric shock","为什么潮湿环境会增加电击风险？","潮湿可能降低皮肤和接触面的电阻，水也可能形成意外导电路径；需评估环境等级、设备适用性和额外防护。"],
["S1","电气危险","detail","S1课程材料 · Arc hazards","电弧产生的烟气为什么不能当作普通烟尘？","可能含高温分解产物、金属烟雾和刺激性/有毒成分；远离烟气并按应急和通风程序处理。"],
["S1","测试与仪表","detail","S1课程材料 · IP ratings","IP35 的两位数字分别描述什么？","第一位 3 表示对规定尺寸固体异物/接近危险部件的防护等级；第二位 5 表示规定条件下的喷水防护。等级的精确定义以相应 IP 表为准。"],
["S1","测试与仪表","detail","S1课程材料 · Electrical test instruments","仪表“量程够”是否就代表适合现场？","不够。还要核对额定电压、CAT 测量类别、探头/附件额定值、环境条件和仪表状态。"],
["S1","现场安全","detail","S1课程材料 · Construction sites","施工现场的临时电缆应防范哪些损伤方式？","碾压、磨损、切割、热源、积水和绊倒风险；布线、支撑和保护依现场程序及设备要求完成。"],
["S1","有害物质","detail","S1课程材料 · Hazardous materials","看到鸟粪或动物排泄物时，为什么不宜干扫？","干扫会使受污染颗粒扬散并造成吸入暴露；依危险评估使用合适控制、PPE 与废弃物处置方法。"],
["S1","风险管理","core","Study Pack p.5–7 · 2.1","风险评估开始前，为什么要先界定工作范围？","要明确具体任务、作业地点、参与人员、设备和工作边界；范围不清会漏掉能源、人员暴露或相邻作业。"],
["S1","风险管理","core","Study Pack p.5–7 · 2.1","风险评估中的“谁可能受影响”应包括哪些人？","不只执行者，还包括同事、其他承包商、客户、公众及可能进入作业区的人；按现场实际识别。"],
["S1","风险管理","detail","Study Pack p.5–7 · 2.1","风险评估为何要考虑作业人员的能力和经验？","同一任务对不同能力人员的风险可能不同；能力不足时应增加监督、培训、替代人员或停止任务。"],
["S1","风险管理","detail","Study Pack p.5–7 · 2.1","风险评估表中“现有控制”要记录什么？","记录已经实际存在且能降低风险的措施，而非计划以后才实施的措施；再判断剩余风险是否需追加控制。"],
["S1","风险管理","detail","Study Pack p.5–7 · 2.1","风险控制措施什么时候需要重新评估？","任务、人员、设备、现场条件或能源状态发生变化，控制措施失效，或出现事故/险情时，应停下并重新评估。"],
["S1","风险管理","core","Study Pack p.5–7 · 2.1","消除危险与降低风险有什么先后关系？","先询问能否消除危险；若不能，再按控制层级选择可行措施降低暴露或后果，并核查残余风险。"],
["S1","风险管理","detail","Study Pack p.5–7 · 2.1","风险评估为什么需要让实际执行任务的人参与？","执行者掌握操作细节和现场变化，参与能发现模板或管理者可能忽略的危险，并提高措施可执行性。"],
["S1","风险管理","detail","Study Pack p.5–7 · 2.1","控制措施写成“注意安全”有什么缺陷？","不可验证、无责任人也不说明动作；应写明具体措施、实施时点、责任人和如何确认有效。"],
["S1","风险管理","detail","Study Pack p.5–7 · 2.1","为什么风险控制后还要检查残余风险？","控制通常降低而非必然消除风险；需确认剩余风险可接受且人员理解，不能接受时应增加控制或停止。"],
["S1","风险管理","core","Study Pack p.8–10 · 2.2","为什么检查表不能代替现场危险源识别？","清单只提示常见危险，无法涵盖每个工地、设备故障和同时作业；需逐步观察实际环境并补充特定危险。"],
["S1","风险管理","detail","Study Pack p.8–10 · 2.2","脚手架、地面和照明为什么属于电气任务的风险评估范围？","跌落、绊倒或视线不足可能导致直接伤害，也可能引发误碰设备、工具失控或电气事故。"],
["S1","风险管理","detail","Study Pack p.8–10 · 2.2","如何区分危险源、危险事件和伤害后果？","危险源是潜在伤害来源；危险事件是暴露/失控发生的情形；后果是由此造成的伤害或损失。"],
["S1","电气危险","core","Study Pack p.11 · 2.3","课程把电击、arcing 和 toxic gases 归为哪类？","教材把它们列作电气危险可能导致的伤害类别；分类用于识别后果，不表示彼此互斥。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","电气间隙和爬电距离分别沿什么路径测量？","电气间隙穿过空气测最短距离；爬电距离沿绝缘材料表面测量。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","绝缘表面污染为何可能影响爬电风险？","灰尘、潮气或导电污染可能形成沿表面的泄漏通路；设备清洁、环境等级和绝缘设计应按产品/标准要求。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","触电危险是否只取决于电压数值？","不只如此；电流路径、持续时间、接触条件、频率、皮肤状态和保护措施都会影响人体后果。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","为什么不能用“低压”推断可以徒手接触？","低压仍可能产生致命电流、灼伤或弧光危险；任何导体是否安全都必须按授权程序隔离并验证。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","电弧危险与普通电击危险的主要差别是什么？","电击主要涉及人体电流通路；电弧可在不直接触碰导体时造成强热、压力、光辐射、飞散物和烟气伤害。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","设备金属外壳正常时不带电，为什么仍要纳入触电风险评估？","绝缘故障可能使外壳意外带电，造成间接接触危险；保护接地、自动切断和验证均不可被假设省略。"],
["S1","电气危险","detail","Study Pack p.11 · 2.3","发现电缆外皮破损但设备仍能运行，应如何判断？","能运行不代表绝缘安全；停止使用/隔离并报告，由授权人员检查和处置，不触摸裸露或疑似带电部位。"],
["S1","激光安全","core","Study Pack p.12 · 2.4","施工用激光仪器的分类主要依据什么？","依据可接近的激光辐射/发射等级；选用设备和防护措施要参考产品标识、说明及适用要求。"],
["S1","激光安全","detail","Study Pack p.12 · 2.4","为什么施工激光束应避免处于人员眼睛高度？","降低光束直接进入眼睛的可能性；同时仍需限制人员接近、正确定位设备并遵照制造商安全说明。"],
["S1","激光安全","core","Study Pack p.12 · 2.4","施工现场使用激光设备前应先做哪些控制？","确认设备等级、操作人员受训、光路方向安全，必要时设警示标志并限制无关人员进入。"],
["S1","激光安全","detail","Study Pack p.12 · 2.4","激光警告标识的作用是什么？","提示人员现场存在光辐射危险和设备使用状态；标识不能替代安全布置、培训和访问控制。"],
["S1","激光安全","detail","Study Pack p.12 · 2.4","激光光路反射为什么也要考虑？","镜面或反光材料可能把光束导向非预期方向；布置设备时需识别反射表面和可能的人员视线。"],
["S1","激光安全","detail","Study Pack p.12 · 2.4","发现激光设备外壳或警示标签损坏时应如何处理？","暂停使用并报告，按设备程序检查；不能仅凭光束看起来较弱就判定安全。"],
["S1","激光安全","detail","Study Pack p.12 · 2.4","激光仪器使用区域为何要管理旁观人员？","无关人员可能直视光束、进入光路或被反射光照射；划定作业区可减少无意暴露。"],
["S1","有害物质","core","Study Pack p.13–14 · 2.5","材料是否含石棉不能确认时，作业应如何开始？","先停止可能扰动材料的工作，避免钻孔、切割或取样，并按场地程序交由合格人员评估。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","石棉风险为什么不能用“少量粉尘”来排除？","风险与材料种类、释放纤维和暴露方式有关；不应自行判断安全剂量，按法规和专业程序处理。"],
["S1","有害物质","core","Study Pack p.13–14 · 2.5","控制含硅粉尘时，源头控制有哪些教材例子？","使用合适的局部抽排/真空控制或湿式抑尘，优先减少粉尘产生；具体方法依材料、工具和现场程序。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","为什么呼吸防护不能替代粉尘源头控制？","呼吸防护是个体防护层，依赖正确选择、适配和佩戴；仍应先减少粉尘产生并控制扩散。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","玻璃棉和岩棉的生物可溶性说明什么，不说明什么？","说明纤维可在体液中溶解并较易清除；不等于吸入无害，仍需控制暴露和粉尘。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","木材、MDF 等作业为什么也要控制空气污染物？","切割、钻孔和打磨会产生可吸入木尘；材料中的添加物/防腐剂也可能影响危害，应依材料数据和程序控制。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","光纤连接/端接产生的玻璃碎屑应如何收集？","避免手触和吹散，使用适合的收集方法并放入规定的锐器容器；保持工作台和衣物清洁。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","为什么光纤碎屑对眼睛尤其危险？","细小玻璃碎片可能刺入眼部且不易察觉；避免揉眼，使用规定护目措施并按暴露程序处理。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","UV 光固化胶作业要关注哪类额外暴露？","紫外线可能伤害眼睛和皮肤；按设备说明设置遮挡、限制直视并采用适用防护。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","什么是空气污染物控制的“优先顺序”思路？","先识别材料和产生源，尽量消除/减少产生，再控制传播，之后采用适当 PPE 与清理/处置措施。"],
["S1","有害物质","detail","Study Pack p.13–14 · 2.5","粉尘作业结束后为什么不宜用压缩空气吹扫？","可能使颗粒重新悬浮并扩散到呼吸区或其他区域；采用适合材料风险的受控清洁方法。"],
["S1","隔离与上锁","core","Study Pack p.15 · 2.6","进行隔离前，为什么要识别所有可能的电源？","设备可能由多个回路、备用电源、控制电源或反向馈电供电；遗漏任一来源都可能使工作部位仍带电。"],
["S1","隔离与上锁","detail","Study Pack p.15 · 2.6","个人危险标签的关键含义是什么？","表明标记人员正在工作，未经授权不得恢复能源；标签应按雇主程序使用，不能替代物理隔离和锁。"],
["S1","隔离与上锁","detail","Study Pack p.15 · 2.6","停用标签与个人危险标签为何不能互换理解？","停用标签用于指出设备故障/不适用或已退出使用；个人危险标签保护作业人员，表示不得重新送能。遵循现场定义。"],
["S1","隔离与上锁","core","Study Pack p.15–16 · 2.6","锁定挂牌在能源控制流程中解决什么问题？","降低他人误操作或意外恢复能源的可能性；仍须完成隔离、残余能量控制和无能量验证。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","隔离点上锁前应怎样处理受影响人员？","按程序通知受影响人员和相关负责人，说明设备停用、工作范围及恢复能源前的沟通要求。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","隔离后发现设备仍可启动，意味着什么？","隔离可能不完整、控制回路仍有电或设备机械状态异常；立即停止并重新识别能源，不继续作业。"],
["S1","隔离与上锁","core","Study Pack p.15–16 · 2.6","“验证无电”要覆盖哪些位置？","覆盖实际作业点及相关导体/接点，并按程序检查所有可能供电路径；只测开关一侧不足以证明工作点安全。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","为什么应在无电验证后再做一次仪表功能确认？","确保测试过程中仪表没有失效；若后测失败，之前的无电读数不能可靠证明设备无电。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","验证无电前发现测试仪表自检失败，下一步是什么？","停止测试并更换/检查仪表；不能继续以该仪表给出无电结论。按授权人员和程序处理。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","隔离了主电源后，还应考虑哪些储能？","电容、旋转惯性、弹簧/重力、气压、液压和热能等；应依风险评估释放或可靠约束并验证。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","隔离边界为什么必须与具体工作点对应？","开关或隔离器可能只切断部分回路；明确边界可确保工作点及所有进入该点的电源均被控制。"],
["S1","隔离与上锁","detail","Study Pack p.15–16 · 2.6","多人共用一个隔离点时，如何减少恢复能源的风险？","依雇主的群组锁定/个人锁定程序让每名作业人员受到保护，并确认全部人员撤离后才按授权解除。"],
["S1","电气危险","core","Study Pack p.16–18 · 2.7","接地故障为何会在地面形成跨步电位差？","故障电流从接地点向周围土壤扩散，地面电位随离故障点距离变化；两脚跨越不同电位就产生跨步电压。"],
["S1","电气危险","detail","Study Pack p.16–18 · 2.7","跨步电压的高低会受哪些现场因素影响？","故障电流、接地/土壤条件、人与故障点距离及步距等都会影响；不要靠近疑似带电地面，按应急程序处置。"],
["S1","电气危险","core","Study Pack p.16–18 · 2.7","发生接地故障时，为什么靠近故障点通常更危险？","地面电位梯度通常在电流注入点附近更大，脚间可能跨越较大的电位差；具体安全距离遵循现场应急指令。"],
["S1","电气危险","detail","Study Pack p.16–18 · 2.7","在疑似跨步电压区域，为什么不能迈大步快速离开？","较大的步距可能让两脚处于差异更大的地面电位；遵从应急程序并联系授权人员，不自行接近故障源。"],
["S1","电气危险","detail","Study Pack p.16–18 · 2.7","接触电压与跨步电压的人体回路分别如何形成？","跨步电压经两脚间的地面电位差；接触电压常在手触及导电物、脚处于另一电位时经身体形成回路。"],
["S1","电气危险","detail","Study Pack p.16–18 · 2.7","直接接触和间接接触的识别重点是什么？","判断被接触部分在正常状态下是否带电：正常带电部分属于直接接触；故障后意外带电的外露部分属于间接接触。"],
["S1","电气危险","detail","Study Pack p.16–18 · 2.7","保护接地为何要保持机械和电气连接都可靠？","松动、腐蚀或断裂会提高故障回路阻抗或失去连续性，可能妨碍保护装置及时动作。"],
["S1","电气危险","core","Study Pack p.17–18 · 2.7","加强绝缘的保护目标是什么？","以相应的绝缘结构降低电击风险，提供教材所述等同于双重绝缘的保护概念；具体设备类别看产品标识。"],
["S1","电气危险","detail","Study Pack p.17–18 · 2.7","RCD 为什么不能替代保护接地？","RCD 是检测剩余电流并切断电源的保护层，动作条件和时间有限；接地、绝缘、隔离等措施仍各有作用。"],
["S1","电气危险","detail","Study Pack p.17–18 · 2.7","等电位联结降低的是哪类风险？","降低可同时触及导电部分之间的电位差，从而减少人体承受的接触电压；不能据此认为系统无故障风险。"],
["S1","高压作业","core","Study Pack p.18–19 · 2.7","高压相关工作开始前为什么要核对最新单线图？","图纸帮助识别网络拓扑、隔离点和可能的供电路径；必须核对版本和现场状态，不能只依赖旧图。"],
["S1","高压作业","detail","Study Pack p.18–19 · 2.7","permit to access 的作用是什么？","作为获授权人员进入指定电气设备/区域开展工作的正式控制文件，边界和条件按电力系统程序确定。"],
["S1","高压作业","detail","Study Pack p.18–19 · 2.7","permit to work 与 access permit 应如何记忆区别？","前者授权在规定条件下开展工作，后者控制进入特定区域/设备；具体名称和法律效力依网络运营方程序。"],
["S1","高压作业","core","Study Pack p.18–19 · 2.7","高压许可文件通常要把哪些边界讲清？","设备/工作范围、隔离和接地状态、限制条件、负责人及有效期间；以授权系统签发的文件为准。"],
["S1","高压作业","detail","Study Pack p.18–19 · 2.7","为什么不得超出许可单写明的工作范围？","许可只覆盖指定设备和边界；越界可能进入带电或未隔离部分，必须停止并重新获得授权。"],
["S1","高压作业","detail","Study Pack p.18–19 · 2.7","接收高压作业许可后，作业人员应先确认什么？","确认设备标识、工作边界、隔离/接地措施和限制条件均与现场一致；不一致时不得开始。"],
["S1","高压作业","detail","Study Pack p.18–19 · 2.7","许可何时可以关闭或归还？","工作完成、人员和工具清点、现场恢复到规定状态并按授权程序交回后；不得由未授权者自行取消隔离。"],
["S1","高压作业","detail","Study Pack p.18–19 · 2.7","高压安全距离为什么不能靠背诵旧教材数值决定？","距离依电压、法规版本、工作方式和网络运营方程序而异；应用现场批准的当前规则和授权指令。"],
["S1","测试与仪表","core","Study Pack p.20 · 2.8","CAT 等级应如何与测量点匹配？","先识别测量点处的瞬态/故障能量环境，再选符合该 CAT 类别及电压额定值的仪表和附件。"],
["S1","测试与仪表","detail","Study Pack p.20 · 2.8","CAT I 的课程用途定位是什么？","用于电子信号等低能量电路测量；不能因电压读数较低就把不匹配的 CAT I 仪表用于高能配电点。"],
["S1","测试与仪表","detail","Study Pack p.20 · 2.8","为什么探头额定值也必须与仪表相容？","探头可能先承受瞬态电压；若附件等级低于仪表，会成为整个测量链的薄弱环节。"],
["S1","测试与仪表","detail","Study Pack p.20 · 2.8","测量类别和额定电压是同一件事吗？","不是。CAT 表示测量环境能量类别，电压额定值表示允许的电压范围；两者都要满足现场要求。"],
["S1","测试与仪表","core","Study Pack p.21 · 2.8","IP 代码第一位数字覆盖哪两类防护信息？","对固体异物进入的防护，以及对接近危险部件的防护等级；应查相应数字的完整表义。"],
["S1","测试与仪表","detail","Study Pack p.21 · 2.8","IP 代码第二位数字不能说明什么？","它描述防水试验条件下的防护，不代表设备在任何浸水、喷射方向或持续时间下都安全。"],
["S1","测试与仪表","detail","Study Pack p.21 · 2.8","为何只看到 IP 数字仍需核对设备安装条件？","防护等级在规定试验条件下成立；安装方向、密封件、开孔、老化和接头都会改变现场实际防护。"],
["S1","测试与仪表","detail","Study Pack p.20–21 · 2.8","使用仪表发现读数异常或不稳定时应如何做？","停止据此作安全判断，检查仪表、附件、量程和连接；由授权人员按程序复测或更换设备。"],
["S1","测试与仪表","detail","Study Pack p.20–21 · 2.8","测试前检查表笔绝缘要看什么？","检查割伤、裂纹、导体外露、护指和连接状态，并确认附件标称等级适合测量环境。"],
["S1","测试与仪表","detail","Study Pack p.20–21 · 2.8","为什么测量完成后要安全收纳测试探头？","防止探头损坏、误触导电部位或留下绊倒/短路危险；按设备说明清洁并存放。"],
["S1","人体电流","core","Study Pack p.22–24 · 2.9","人体电流危险为什么不能只用“是否疼痛”判断？","感知会受电流路径、持续时间、频率和个体状态影响；轻微感觉也不能证明安全，应按程序防止接触。"],
["S1","人体电流","detail","Study Pack p.22–24 · 2.9","教材指出哪些常见人体电流路径可能经过重要器官？","手到手、手到脚或头到脚的路径可能经过胸腔/重要器官；防护应避免人体成为回路。"],
["S1","人体电流","detail","Study Pack p.22–24 · 2.9","50 Hz 交流为什么在课程中被特别强调？","教材用它说明常见工频交流对人体的危险影响；不能据此推断其他频率或直流必然安全。"],
["S1","人体电流","detail","Study Pack p.22–24 · 2.9","触电事故现场第一优先是什么？","先确保救援者不进入带电危险；按应急程序隔离电源、呼叫急救并由受训人员施救。"],
["S1","人体电流","core","Study Pack p.22–24 · 2.9","电容器断电后为何仍要防止再次充电？","电容器可保留电荷，且某些电路条件会使其电压回升；按规定放电并在工作点验证。"],
["S1","人体电流","detail","Study Pack p.22–24 · 2.9","RCD 的存在能否证明回路可以安全触摸？","不能。它只是保护措施之一，仍需正确隔离、验证无电并遵循授权程序。"],
["S1","现场安全","core","Study Pack p.25–29 · 2.9","施工场所的风险评估还应考虑哪些非电气现场变化？","天气、积水、地面、照明、交通、其他承包商活动和可燃/易燃环境等，按作业地点逐项识别。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","施工区临时配电箱为什么要防雨并保持可识别？","减少进水风险并帮助人员区分设备状态和供电用途；防护和布置依现场程序及设备额定要求。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","临时线路跨越通道时需要控制什么风险？","绊倒、碾压、磨损及绝缘损伤；采用批准的支撑或防护方式，不让电缆被门窗/车辆挤压。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","延长线在使用前要检查哪些损伤？","护套和插头、连接器、应力消除、可见导体以及过热/受潮迹象；损坏设备应退出使用并报告。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","为什么不能把临时电缆盘着长时间带负载使用？","盘绕会影响散热并可能导致过热；按电缆盘制造商的负载/展开要求和现场程序使用。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","施工现场的配电保护装置需要怎样管理？","按场地规则选择、检查、测试和防止误操作；不得旁路保护或自行改变设置。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","为什么临时和永久电气线路要清楚区分？","减少误接、误隔离和设备混用，让施工人员知道线路用途及其保护状态。"],
["S1","现场安全","detail","Study Pack p.25–29 · 2.9","电缆经过热源、锐边或可移动部件附近时要考虑什么？","热损伤、磨穿、夹挤和机械切割；改变路线或加装适合的保护与固定，并复核设备边界。"],
["S2","测量与标记","core","Study Pack p.31","什么叫 marking out（放样）？","把线、圆、轮廓、中心点等必要信息转移到工件上，标明加工位置和范围，并为后续操作提供依据。"],
["S2","测量与标记","core","Study Pack p.31","测量时 datum（基准）是什么？为什么从基准测量？","datum 是作为测量起点的边线或参考点。从同一基准测量可保持尺寸一致，减少累积误差。"],
["S2","测量与标记","core","Study Pack p.31","钢尺读数怎样避免视差误差？","眼睛正对被读刻度，使视线与刻度垂直；斜着看会产生视差。"],
["S2","测量与标记","detail","Study Pack p.31","钢尺主要适合测量什么工件？还有什么用途？","测量平直或平面的尺寸，也可作为直边，例如裁切定子绝缘片时作直边。"],
["S2","测量与标记","detail","Study Pack p.31","为什么不同钢尺的读数精细程度会不同？","刻度分度不同：有的最小分度为 1 mm，有的为 0.5 mm。"],
["S2","测量与标记","detail","Study Pack p.31","用钢卷尺测量电缆路径长度时，教材提醒了什么？","布卷尺可用于测量电缆路径长度以供压降计算；钢卷尺不要在带电设备附近使用。"],
["S2","测量与标记","core","Study Pack p.31","工程师直角尺在车间中检验什么？","检验直角/方正度，是车间检验 squareness 的标准工具。"],
["S2","测量与标记","detail","Study Pack p.31","怎样用翻转法检查工程师直角尺？","沿直边划线，将直角尺翻转后对照原线；若偏离，说明直角尺精度有问题。"],
["S2","测量与标记","detail","Study Pack p.31","scriber（划线器）用来做什么？","在金属表面划出细线，标记加工位置；尖端可为热处理钢或硬质合金。"],
["S2","测量与标记","detail","Study Pack p.31","镀锌金属表面划线不明显时可用什么？","涂 Prussian blue（工程师蓝/划线蓝）增加对比度；也可用墨水、粉笔或记号笔突出标记。"],
["S2","测量与标记","detail","Study Pack p.31","什么是 witness marks（见证点）？怎样做？","在划线上用中心冲轻打若干点，防止划线被擦掉。"],
["S2","测量与标记","detail","Study Pack p.31","外卡钳用于测量什么？","外部尺寸的比较测量与尺寸转移；通常不是直接读出数值的刻度量具。"],
["S2","测量与标记","detail","Study Pack p.31","内卡钳用于测量什么？","测量孔或空腔等内部尺寸。"],
["S2","测量与标记","core","Study Pack p.31","Jenny caliper（奇脚卡钳）有什么用途？","转移/标出设定尺寸；直脚靠基准边，弯脚划线。可沿边缘划平行线，也可找圆形或方形截面的中心。"],
["S2","测量与标记","detail","Study Pack p.31","Jenny caliper 还有哪些名称？","Odd-leg caliper 或 hermaphrodite caliper。"],
["S2","测量与标记","detail","Study Pack p.31","spring dividers（弹簧分规）有什么用途？","划圆，以及转移尺寸。"],
["S2","测量与标记","core","Study Pack p.32","千分尺的分辨率怎样从教材给出的结构得到？","套筒每转前进 0.5 mm，微分筒有 50 格，因此每格为 0.01 mm。"],
["S2","测量与标记","core","Study Pack p.32","教材图示千分尺读数：套筒 14 mm，微分筒 32 格，结果是多少？","14 + 32×0.01 = 14.32 mm。"],
["S2","测量与标记","detail","Study Pack p.32","千分尺读数先看哪一部分？","先读微分筒左侧套筒主刻度，再读与基准线对齐的微分筒刻度，最后相加。"],
["S2","测量与标记","core","Study Pack p.32","教材建议在什么精度要求下使用千分尺？","需要小于 0.5 mm 精度的精密测量时，使用千分尺。"],
["S2","测量与标记","detail","Study Pack p.32","千分尺主要测量哪类尺寸？","教材介绍其用于精确测量工件外径/厚度等尺寸；应按量具结构正确读数。"],
["S2","测量与标记","core","Study Pack p.32","游标卡尺可以测量哪三类尺寸？","工件外径、孔内径、孔深。"],
["S2","测量与标记","detail","Study Pack p.32","游标卡尺为何被称为组合两种刻度的量具？","读数结合主尺与游标尺两套刻度。"],
["S2","测量与标记","detail","Study Pack p.33","组合两种不同刻度来测量的工具是什么？","游标卡尺（vernier caliper）。"],
["S2","夹持与切割","core","Study Pack p.34","手用钢锯是什么结构？","有刚性锯背/弓架、可更换金属锯条的弓形锯。"],
["S2","夹持与切割","core","Study Pack p.34","钢锯锯条齿尖通常朝哪个方向？切割时怎样施力？","齿尖朝前；向前切割行程施加向下压力，回程放松压力。"],
["S2","夹持与切割","core","Study Pack p.34","钢锯切割时至少要有多少齿同时接触工件？","至少 3 齿同时接触，减少挂齿和损坏。"],
["S2","夹持与切割","core","Study Pack p.34","教材推荐的手锯常规切割速度是多少？","每分钟约 40–50 个往复行程；较硬材料应更慢。"],
["S2","夹持与切割","detail","Study Pack p.34","开始钢锯切割前为什么先轻划几下？","先在材料表面划出引导槽，帮助锯条沿正确路径切入。"],
["S2","夹持与切割","core","Study Pack p.34","3 mm 厚材料适合选多少齿/25 mm 的钢锯条？","24 齿/25 mm；教材表中 24 齿适用于 1.6–3 mm。"],
["S2","夹持与切割","detail","Study Pack p.34","钢锯条 14、18、24、32 齿分别适合什么厚度？","14 齿：2.4–25 mm；18 齿：1.6–8 mm；24 齿：1.6–3 mm；32 齿：小于 1.6 mm。"],
["S2","夹持与切割","detail","Study Pack p.34","钢锯条的 raker tooth pattern（交错齿）有什么作用？","形成略宽于锯条本体的锯缝，使锯条不易夹住，并获得较平顺切口。"],
["S2","夹持与切割","detail","Study Pack p.34","哪些情况会损坏钢锯条？","把新锯条放进较窄的旧锯缝、张力过大、工件夹持不牢、锯条规格选错。"],
["S2","夹持与切割","detail","Study Pack p.34","锯钢材时教材建议怎样处理切口？","润滑切口以减轻摩擦；教材举例使用渗透润滑剂或自动变速箱油。"],
["S2","夹持与切割","detail","Study Pack p.34","钢锯用完后要做哪些保养？","清掉锯条上的润滑剂和材料颗粒，并释放锯架张力。"],
["S2","夹持与切割","detail","Study Pack p.34","圆形硬质合金颗粒锯条可切割哪些材料/形状？","因其 360° 圆周可切削，可在任意方向切割金属、瓷砖、陶瓷、墙板的槽、角和曲线。"],
["S2","夹持与切割","detail","Study Pack p.34","动力钢锯与手锯的切割行程有何区别？","教材指出动力钢锯在回程切割；适用于角钢、棒材、扁钢、槽钢、管材等金属型材。"],
["S2","夹持与切割","core","Study Pack p.35","冷凿用于加工什么材料？","切削、成形或去除比凿刃软的冷态金属，如软铁、铝、黄铜、铜。"],
["S2","夹持与切割","core","Study Pack p.35","冷凿切削软金属和硬金属时，刃口角度分别是多少？","软金属约 60°；硬金属约 70°。"],
["S2","夹持与切割","detail","Study Pack p.35","使用冷凿前检查哪两个部位？","切削刃应锋利；受锤击的凿头不得蘑菇状变形或崩裂。"],
["S2","夹持与切割","detail","Study Pack p.35","用冷凿作剪切/剔凿时，凿刃斜面如何放置？","让切削刃的斜面贴合剪切平面。"],
["S2","夹持与切割","core","Study Pack p.35","用冷凿作业要怎样保护自己？","戴护目镜或面屏，并戴手套；教材还提到可在凿杆上加橡胶防护罩。"],
["S2","夹持与切割","core","Study Pack p.35","薄板剪（tin snips）最大可剪多厚的板材？","教材给出的上限为 1 mm。"],
["S2","夹持与切割","detail","Study Pack p.35","薄板剪有哪些切割方向/类型？","有适合直线、向左曲线或向右曲线的不同形状和规格。"],
["S2","夹持与切割","detail","Study Pack p.35","右撇子使用薄板剪时，废料应放在哪侧？左撇子呢？","右撇子让废料在右侧；左撇子让废料在左侧。"],
["S2","夹持与切割","core","Study Pack p.35","使用薄板剪时要防范什么，穿戴什么？","切边非常锋利，戴手套和安全眼镜；保持枢轴螺栓适当调整，使用后给刀片和枢轴上油。"],
["S2","夹持与切割","core","Study Pack p.35","bolt cutter（断线/螺栓剪）适合切什么？","圆钢棒、软螺栓或小方钢条；利用长柄放大施加到刃口的夹切力。"],
["S2","夹持与切割","core","Study Pack p.36","台钳的 buttress thread（锯齿形螺纹）适合承受什么？","适合承受单一方向的轴向推力。"],
["S2","夹持与切割","detail","Study Pack p.36","为什么不能用锤子敲铸铁台钳本体或钳口？","台钳通常为铸铁，抗压但受冲击易脆裂。"],
["S2","夹持与切割","detail","Study Pack p.36","台钳钳口的交叉齿纹有什么作用？","增加夹持摩擦力，使工件不易滑动。"],
["S2","夹持与切割","core","Study Pack p.36","台钳的软钳口（soft jaws）何时使用？","夹持表面较软或精加工工件时，保护表面不被硬质钳口压出痕迹。"],
["S2","夹持与切割","detail","Study Pack p.36","machine vice（机用虎钳）常安装/使用在哪里？","安装在钻床等机床工作台上，夹持工件以便准确加工。"],
["S2","夹持与切割","core","Study Pack p.37","锉刀的长度如何测量？","测量锉身从尖端到跟部（不含锉柄）的长度。"],
["S2","夹持与切割","core","Study Pack p.37","bastard-cut、second-cut、smooth-cut 三种锉纹，齿数由少到多如何排列？","Bastard-cut 最少；second-cut 较多；smooth-cut 最多。齿越粗，表面越粗糙、去料通常越快。"],
["S2","夹持与切割","detail","Study Pack p.37","木材或较软材料可用哪类锉？","木材可用 rasp（木锉）；铝等软材料可用 dreadnought file（粗齿曲列锉）。"],
["S2","夹持与切割","detail","Study Pack p.37","flat file 和 safe-edge file 的用途分别是什么？","平锉用于平面快速去料；安全边锉可锉一个面而不损伤相邻面。"],
["S2","夹持与切割","detail","Study Pack p.37","half-round file 和 rat-tail file 分别适合什么？","半圆锉适用于圆孔、凹面和平面；圆锉（rat-tail）用于扩大孔和槽。"],
["S2","夹持与切割","detail","Study Pack p.37","triangle file、square file、warding file 分别适合什么？","三角锉用于角部、平面及刃口角度；方锉用于方孔；薄扁的 warding file 用于狭窄空间。"],
["S2","夹持与切割","core","Study Pack p.37","锉刀为何必须安装锉柄？","防止锉刀尖柄（tang）刺伤手，并提供安全握持。"],
["S2","夹持与切割","detail","Study Pack p.37","安装锉柄时能否用锤子把锉刀打入？","不能用锤子敲入；将尖柄插入柄孔，再把柄轻敲在平面上使其就位。"],
["S2","夹持与切割","detail","Study Pack p.37","file card（锉刷）用于什么？","清除夹在锉齿间的金属屑等堵塞物，避免堵塞导致工件表面划伤。"],
["S2","夹持与切割","detail","Study Pack p.37","emery cloth（砂布）包在锉刀上有什么用途？","按锉削动作打磨工件，获得更光滑表面。"],
["S2","夹持与切割","detail","Study Pack p.37","教材提到 glass paper 可用于电机的什么部位？","用于抛光电机端盖/端罩法兰（end-shield flanges）；也提到用带油砂布清洁抛光轴。"],
["S2","夹持与切割","core","Study Pack p.37","持锉时基本动作和防护是什么？","双手控制锉刀，向前以稳定轻压力锉削，回程同样控制；金属锉削时戴护目镜/安全眼镜。"],
["S2","钣金与紧固","core","Study Pack p.38","教材怎样定义 sheet metal（薄板金属）？","厚度小于 6 mm 的金属板材。"],
["S2","钣金与紧固","detail","Study Pack p.38","教材列举哪些薄板材料？","低碳钢、不锈钢、铜、铝、黄铜、磷青铜；可为黑色金属、有色金属或合金板。"],
["S2","钣金与紧固","detail","Study Pack p.38","薄板上的涂层可能有什么用途？","控制腐蚀、提高耐久性，并增加对磨损和化学品的抵抗；例如粉末涂层、镀锌、镀锡、镀镍、镀镉。"],
["S2","钣金与紧固","core","Study Pack p.38","薄板常见的连接紧固方式有哪些？","抽芯铆钉、机螺纹螺钉/螺栓、自攻螺钉、敲入式螺钉（drive screws）。"],
["S2","钣金与紧固","core","Study Pack p.38","pop rivet（抽芯铆钉）在什么情况下特别有用？","连接处只有一侧可接近时，抽芯铆钉可从单侧完成连接。"],
["S2","钣金与紧固","detail","Study Pack p.38","处理薄板边缘时为什么戴皮手套？","薄板剪切边很锋利，容易造成割伤。"],
["S2","钻头与钻孔","core","Study Pack p.40","centre punch（中心冲）在钻孔前有什么作用？","在放样圆弧/圆心位置打出中心凹点，帮助准确定位钻孔。"],
["S2","钻头与钻孔","detail","Study Pack p.40","教材列出的中心冲标记角度有哪些？","标中心的中心冲尖端约 60°；用于轻作见证标记的冲点约 40°。"],
["S2","钻头与钻孔","detail","Study Pack p.40","手摇木工弓钻/木工螺旋钻（auger bit）适合什么？","用手摇钻架在木材上钻较大孔，教材举例最大约 25 mm。"],
["S2","钻头与钻孔","detail","Study Pack p.40","spade/flat wood bit（扁木工钻头）适合什么？","在木材中钻较大直径孔。"],
["S2","钻头与钻孔","core","Study Pack p.40","麻花钻的 flutes（螺旋槽）和螺旋角有什么作用？","槽把切屑带出孔外；螺旋形状产生正前角，有利于切削。"],
["S2","钻头与钻孔","detail","Study Pack p.40","麻花钻的 cutting point 和 cutting edge 分别是什么？","钻尖负责切入材料；两侧切削刃承担切削并形成孔。"],
["S2","钻头与钻孔","detail","Study Pack p.40","教材列举的五种麻花钻类型是什么？","钛涂层、硬质合金头、钴、碳钢、高速钢（HSS）。"],
["S2","钻头与钻孔","core","Study Pack p.40","普通金属和木材钻孔常用哪种教材所列钻头材料？","金属常用 HSS；木材常用碳钢钻头。HSS 能承受较高温度。"],
["S2","钻头与钻孔","detail","Study Pack p.40","怎样测量麻花钻直径？","在两条切削刃外缘之间测量，教材建议用千分尺。"],
["S2","钻头与钻孔","core","Study Pack p.40","教材给出的钻头转速规则是什么？","直径小于 4.25 mm：约 1200–1500 rpm；直径达到或大于 4.25 mm：约 900 rpm。按教材记忆，实际仍须核对设备/材料要求。"],
["S2","钻头与钻孔","core","Study Pack p.40","砖石钻头靠什么特征钻砖、混凝土等材料？","钻头端部有硬质合金头；教材列举砖、砌块、石材、采石砖和混凝土，低速并使用冲击动作。"],
["S2","钻头与钻孔","detail","Study Pack p.40","drill gauge（钻头规）有什么用途？","检查/识别钻头尺寸。"],
["S2","钻头与钻孔","core","Study Pack p.40","hole saw 或 fly cutter 适合什么任务？","在薄板等材料中加工较大直径的孔；飞刀/划圆器可按设定半径划切圆孔。"],
["S2","钻头与钻孔","detail","Study Pack p.41","孔锯由哪三部分组成？","连接普通电钻的心轴（arbor）、导向钻（pilot bit）和孔锯锯筒/锯片。"],
["S2","钻头与钻孔","core","Study Pack p.41","用孔锯怎样减少出口侧撕裂？","从一侧钻入，在即将钻穿前停止；翻到另一面完成切割，使两侧孔口更整齐。"],
["S2","攻丝与套丝","core","Study Pack p.41","公制螺纹 M10 × 1.5 中，M、10、1.5 各表示什么？","M 表示公制螺纹；10 mm 是公称外径；1.5 mm 是螺距。"],
["S2","攻丝与套丝","core","Study Pack p.41","公制螺距（pitch）如何定义？","沿螺纹轴线方向，相邻螺纹对应点之间的距离。"],
["S2","攻丝与套丝","detail","Study Pack p.41","公制粗牙螺纹通常怎样标注？","省略螺距，只写 M 加公称尺寸，例如 M10。"],
["S2","攻丝与套丝","core","Study Pack p.41","60°公制螺纹的攻丝底孔公式是什么？","底孔直径 = 螺纹公称外径 − 螺距；教材说结果约形成 68%–77% 的螺纹深度。"],
["S2","攻丝与套丝","core","Study Pack p.42","M5 × 0.8 的攻丝底孔多大？","5 − 0.8 = 4.2 mm。"],
["S2","攻丝与套丝","core","Study Pack p.42","M8 × 1.25 和 M8 × 1 的底孔分别多大？","M8 × 1.25：6.8 mm；M8 × 1：7.0 mm。"],
["S2","攻丝与套丝","core","Study Pack p.42","M10 × 1.5 和 M10 × 1.25 的底孔分别多大？","分别为 8.5 mm 和 8.8 mm。"],
["S2","攻丝与套丝","core","Study Pack p.42","M12 × 1.75 和 M12 × 1.25 的底孔分别多大？","分别为 10.2 mm 和 10.8 mm。"],
["S2","攻丝与套丝","detail","Study Pack p.42","M27 × 3 的攻丝底孔多大？","27 − 3 = 24 mm。"],
["S2","攻丝与套丝","core","Study Pack p.42","丝锥（tap）切削的是什么螺纹？","在孔内切出内螺纹，称为 tapping（攻丝）。所用丝锥必须与紧固件的螺距匹配。"],
["S2","攻丝与套丝","detail","Study Pack p.42","丝锥的槽和方柄分别有什么作用？","槽形成切削刃并排出切屑；方柄与丝锥扳手配合。"],
["S2","攻丝与套丝","core","Study Pack p.42","三种常见丝锥是什么？各自的主要用途？","先导/锥形（taper）易于起牙；中间（intermediate）继续切削；底锥/塞规式（plug）用于盲孔底部完成全牙，不用于起牙。"],
["S2","攻丝与套丝","detail","Study Pack p.42","锥形丝锥可用于通孔和盲孔吗？","可用于起牙；通孔需让锥形丝锥贯穿，才能使全长螺纹达到完整深度，也可用于盲孔起始。"],
["S2","攻丝与套丝","detail","Study Pack p.42","中间丝锥通常用于什么阶段？","接在锥形丝锥之后继续切削；可用于完成通孔或盲孔的螺纹。"],
["S2","攻丝与套丝","core","Study Pack p.43","攻丝时为什么每转约四分之一圈就反转？","折断切屑并减少螺纹撕裂。"],
["S2","攻丝与套丝","detail","Study Pack p.43","攻丝时丝锥如何与孔对正？","使丝锥与孔轴线一致，可用工程师直角尺辅助检查垂直/对中。"],
["S2","攻丝与套丝","detail","Study Pack p.43","攻丝为什么使用切削润滑剂？","让切削更顺畅，减少螺纹撕裂。"],
["S2","攻丝与套丝","core","Study Pack p.43","丝锥受力过大会有什么危险？","丝锥为硬化金属，受力过大会断裂或崩碎；佩戴眼部防护，不能强行加力。"],
["S2","攻丝与套丝","core","Study Pack p.43","三种常见板牙（die）是什么？","可调半圆板牙（half die）、按钮/开口板牙（button/split die）、六角板牙（die nut）。"],
["S2","攻丝与套丝","core","Study Pack p.43","板牙用于加工哪类螺纹？","在杆件或导管等外圆表面切出外螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.43","按钮板牙开始切削时如何调整？","第一刀先不调小，之后逐步减小切削量，达到所需螺纹尺寸。"],
["S2","攻丝与套丝","core","Study Pack p.43","die nut（六角板牙/修牙板牙）主要用于什么？","清理生锈或损坏的外螺纹，也可检查现有螺纹；规格固定，用扳手转动。"],
["S2","攻丝与套丝","detail","Study Pack p.43","用板牙在杆件上起牙前要做什么？","杆端倒角；牢固支撑工件；板牙保持与工件轴线垂直；用切削润滑剂并定期刷净螺纹。"],
["S2","攻丝与套丝","core","Study Pack p.43","断螺栓取出器（extractor）怎样工作？","先在断件中钻孔，插入取出器并逆时针转动；其咬住孔壁，将断件旋出而不损伤内螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.43","取出器有哪些常见槽形？使用时有什么危险？","直槽和螺旋槽；取出器硬而脆，过度施力可能断裂，须戴护目镜。"],
["S2","电动工具","core","Study Pack p.44","使用电动工具前先检查教材要求的电气标签是什么？","确认工具有电气测试标签，表明已通过相应测试。"],
["S2","电动工具","core","Study Pack p.44","冲击钻通常有哪些三种工作模式？","普通钻孔、仅锤击、钻孔加锤击。组合模式可快速钻砖石孔。"],
["S2","电动工具","detail","Study Pack p.44","教材给出的冲击钻能力示例是什么？","部分冲击钻可达每分钟 4200 次冲击，配 4–22 mm 砖石钻头。"],
["S2","电动工具","detail","Study Pack p.44","可调离合电动螺丝刀有什么作用？","提供不同扭矩，以便将多种紧固件旋入软或硬材料。"],
["S2","电动工具","core","Study Pack p.44","热风枪在电气行业常见的两种用途是什么？","收缩热缩套管、弯曲 PVC 导管。"],
["S2","电动工具","detail","Study Pack p.44","教材给出的热风枪出风温度范围是多少？","约 315–538 °C；使用时戴安全眼镜并注意高温表面/气流。"],
["S2","电动工具","core","Study Pack p.45","nibbler（电动咬口机）适合怎样切割薄板？","适合在薄板金属上切直线和曲线。"],
["S2","电动工具","core","Study Pack p.45","立式钻床除钻孔外还能做哪些加工？","铰孔、沉孔/锪孔及扩孔。"],
["S2","电动工具","core","Study Pack p.45","立式钻床加工时工件应如何固定？","放在虎钳中或夹紧在工作台/底座上；不能用手直接握住工件钻削。"],
["S2","电动工具","detail","Study Pack p.45","直接夹在钻床台面的工件下垫木板有什么目的？","防止钻头钻伤工作台面。"],
["S2","电动工具","core","Study Pack p.45","立式钻床附近哪些穿戴/行为会造成卷入危险？","手套、宽松衣物、首饰、散开的长发可能被夹头或钻头卷入；长发需束好。"],
["S2","电动工具","detail","Study Pack p.45","钻完孔后怎样清理钻床上的金属屑？","用刷子清除，不用手直接扫金属屑。"],
["S2","电动工具","core","Study Pack p.45","砂轮机砂轮由什么制成？","由结合剂粘结的磨料构成。"],
["S2","电动工具","core","Study Pack p.45","什么是砂轮 ring test（敲击/音响检查）？如何判断？","用非金属物轻敲砂轮；若没有清脆金属回响，教材判定砂轮不安全，不应使用。"],
["S2","电动工具","detail","Study Pack p.45","砂轮机工作托架应如何设置？","托架应略高于砂轮中心，间隙约 1.5 mm。"],
["S2","电动工具","core","Study Pack p.45","使用砂轮机时为什么不能磨砂轮侧面或软金属？","教材明确要求不要用砂轮侧面磨削，也不要磨铜、铝等软材料，以防不当受力/砂轮堵塞等危险。"],
["S2","电动工具","core","Study Pack p.45","角磨机打磨时，磨片与工件夹角应是多少？","15°–30°。"],
["S2","电动工具","core","Study Pack p.45","角磨机是否适合切割金属？","教材指出角磨机不应用于金属切割；应使用专用切割机。"],
["S2","电动工具","detail","Study Pack p.45","角磨机放下前要满足什么条件？","先等砂轮完全停止转动，再放下工具。"],
["S2","电动工具","core","Study Pack p.45","使用角磨机时教材列举哪些防护装备？","手套、安全眼镜、钢包头安全鞋、护膝、耳塞和工作服；按风险还需面屏等。"],
["S2","通用手工具","core","Study Pack p.46","电工最常见的两种螺丝刀头型是什么？","一字/平刃（flat-blade）和十字（Phillips）。"],
["S2","通用手工具","core","Study Pack p.46","电工使用螺丝刀有什么绝缘等级要求？","教材要求电工用螺丝刀绝缘至 1000 V，并获澳大利亚标准认可。"],
["S2","通用手工具","detail","Study Pack p.46","平刃螺丝刀按什么尺寸选？","按刀头宽度（毫米）测量/标注。"],
["S2","通用手工具","detail","Study Pack p.46","Phillips 十字螺丝刀为何较能抵抗滑脱？","十字槽与刀头的接合让刀头贴合螺钉槽，可施加扭矩并减少滑脱/损坏槽口。"],
["S2","通用手工具","detail","Study Pack p.46","Phillips 螺丝刀常见规格如何表示？","用编号表示，如 #0、#1、#2、#3。"],
["S2","通用手工具","core","Study Pack p.47","组合钳（combination pliers）有哪些常见用途？","夹持多种形状物件，也可剪切不同规格导线/电缆。"],
["S2","通用手工具","core","Study Pack p.47","斜口钳（diagonal cutters）的刃口有什么特点？","两刃在接合点呈斜向布置，用于剪切导线等。"],
["S2","通用手工具","detail","Study Pack p.47","剥线工具的两种类型是什么？","刀具式剥线工具和机械式剥线器。"],
["S2","通用手工具","core","Study Pack p.47","教材所说电缆剪适合剪切哪类电缆？","适用于截面积不超过 25 mm² 的非铠装多股铝或铜电缆。"],
["S2","通用手工具","core","Study Pack p.47","压接工具（crimping tool）的作用是什么？","压缩端子/接头，使其紧密固定在电缆导体上。"],
["S2","通用手工具","detail","Study Pack p.47","multigrips（可调水泵钳）适合处理什么？","夹持/旋松圆形物件，尤其没有六角头可供扳手咬合时。"],
["S2","通用手工具","detail","Study Pack p.47","vice grips（锁紧钳）常用于哪些操作？","夹紧、扭转、转动或固定工件。"],
["S2","通用手工具","core","Study Pack p.48","Allen/Unbrako key 用于驱动什么紧固件？","内六角孔头螺钉或螺栓。"],
["S2","通用手工具","detail","Study Pack p.48","内六角扳手的规格按什么尺寸确定？","按六角形对边尺寸确定，不按总长度测量。"],
["S2","通用手工具","core","Study Pack p.48","拉马（puller）用于拆卸什么？","利用机械优势拆卸紧配合的滚珠/滚柱轴承和齿轮，尽量避免损伤。"],
["S2","通用手工具","detail","Study Pack p.48","使用拉马时爪、丝杆和轴线如何对齐？","拉爪均匀咬住零件，丝杆与轴/轴承中心线对齐；教材建议给丝杆润滑。"],
["S2","通用手工具","detail","Study Pack p.48","教材对难拆轴承提到什么辅助方法？","可给丝杆加油，并对顽固轴承使用两次有力锤击辅助；需遵守安全防护，避免损伤部件。"],
["S2","通用手工具","core","Study Pack p.49","rawhide mallet（生皮锤）在电气装配中的典型用途是什么？","电气装配工常用它拆装设备，例如电动机，可减少对工件表面的损伤。"],
["S2","通用手工具","detail","Study Pack p.49","ball-pein hammer（球头锤）的球头用于什么？","用于把金属敲打/成形到所需形状。"],
["S2","拆卸与环境","core","Study Pack p.49","开始拆卸前首先要明确什么？","先明确目标和结果要求：是整体检修还是只拆部件，并确认需满足的安全、布线规则及其他要求。"],
["S2","拆卸与环境","core","Study Pack p.49","教材把拆卸作业的首要目标定为什么？","工作人员安全始终是首要目标。"],
["S2","拆卸与环境","core","Study Pack p.49","拆卸前如何处理电气、气动、液压等能源？","开始拆卸前断开所有能源，并在作业区进行挂牌或上锁隔离（tag/lock out）。"],
["S2","拆卸与环境","detail","Study Pack p.49","制定拆卸方法还应考虑哪些方面？","所需 PPE 和危险源、作业地点、废物/清洁液/退役电缆和零件的收集处置，以及完成工作所需机械工具。"],
["S2","拆卸与环境","core","Study Pack p.49","装配与拆卸是什么关系？装配完成后还需做什么？","装配通常按拆卸的反向顺序进行；必须安排测试以验证装配结果。"],
["S2","拆卸与环境","detail","Study Pack p.49","为什么教材强调电气/电子设备报废处理？","设备寿命缩短会增加废弃物处理挑战；设置不透水区域进行去污染、拆解和分类，可促进再用、回收和资源回收。"],
["S2","焊接与钎焊","core","Study Pack p.50","教材列举软钎焊的三类主要危险是什么？","高温、焊接烟气/ fumes，以及焊料成分；另有熔融焊料飞溅和电缆绝缘受热产生的有毒烟气。"],
["S2","焊接与钎焊","core","Study Pack p.50","软钎焊作业教材要求哪些 PPE/工程控制？","侧护安全眼镜、皮手套、棉质长袖衣物，以及足够的整体或局部排风；应在通风良好处操作。"],
["S2","焊接与钎焊","detail","Study Pack p.50","软钎焊结束后如何减少残留污染？","用肥皂彻底清洗双手和面部。"],
["S2","焊接与钎焊","core","Study Pack p.50","教材定义软钎焊的温度边界是什么？","填料金属熔点低于 427 °C，且低于母材熔点；母材不熔化。"],
["S2","焊接与钎焊","detail","Study Pack p.50","教材建议的无铅软焊料成分是什么？","99.3% 锡、0.7% 铜。"],
["S2","焊接与钎焊","detail","Study Pack p.50","软钎焊中的 flux（助焊剂）有什么作用？","清洁待焊表面并帮助焊料流动/润湿。"],
["S2","焊接与钎焊","core","Study Pack p.50","教材建议先怎样加热待焊导体？","火焰/热源先垂直对准导体，使热量均匀传入接头；不要把火焰移向绝缘层，以免烧伤绝缘。"],
["S2","焊接与钎焊","detail","Study Pack p.50","焊料接触接头后若没有熔化，应怎么办？","移开焊料，继续加热接头；不要用焊料直接填补冷接头。"],
["S2","焊接与钎焊","core","Study Pack p.50","焊料怎样进入接头间隙？","熔化的焊料通过毛细作用被吸入接头。"],
["S2","焊接与钎焊","core","Study Pack p.51","银钎焊/硬钎焊的接合原理是什么？","熔化填料金属（合金），靠毛细作用流入接缝；母材不熔化，填料与母材形成冶金结合。"],
["S2","焊接与钎焊","core","Study Pack p.51","教材给出的硬钎焊温度范围是多少？","约 593–871 °C，低于母材熔点。"],
["S2","焊接与钎焊","detail","Study Pack p.51","银钎焊接头的性能特点是什么？","可形成气密/液密接头，并能承受压力、冲击和振动载荷。"],
["S2","焊接与钎焊","detail","Study Pack p.51","为什么硬钎焊也需控制烟气风险？","金属加热会产生烟气；教材提示硬钎焊具有潜在危害。"],
["S2","焊接与钎焊","core","Study Pack p.51","教材为什么称 MIG 焊相对容易上手？","焊丝由设备连续送入电弧/熔池，不需要像某些工艺那样手动逐段添加焊条。"],
["S2","焊接与钎焊","core","Study Pack p.52","MIG 焊调整中教材强调哪两个关键参数？","电压和送丝速度，两者必须配合。"],
["S2","焊接与钎焊","detail","Study Pack p.52","MIG 焊电压提高或降低，对焊池有什么影响？","电压较高，焊池较热；电压较低，焊池较冷。薄板倾向用较冷焊池，厚板用较热焊池。"],
["S2","焊接与钎焊","detail","Study Pack p.52","教材还列举哪两类焊接工艺？","TIG（钨极惰性气体保护焊）和电弧焊。"],
["S2","测量与标记","core","Study Pack p.31 · 3.2","放样的结果应包含哪些空间信息？","可以是线、圆、轮廓和中心标记，用来表达加工位置与范围；标记需清晰且对应工作图样。"],
["S2","测量与标记","detail","Study Pack p.31 · 3.2","为什么钢尺测量要把眼睛移到刻度正上方？","避免视线斜交刻度造成视差，导致读数偏大或偏小。"],
["S2","测量与标记","detail","Study Pack p.31 · 3.2","工程师蓝（Prussian blue）在放样中解决什么问题？","给金属表面提供对比背景，让划线更清楚；它是标记辅助，不是永久尺寸标记。"],
["S2","测量与标记","core","Study Pack p.31 · 3.2","什么时候需要沿划线做轻微见证点？","划线可能被擦除、后续操作会遮住线时，可沿线轻点中心冲保留定位；不能把工件冲变形。"],
["S2","测量与标记","detail","Study Pack p.31 · 3.2","钢尺和划线器在放样中的分工是什么？","钢尺提供长度基准/直边，划线器在金属表面刻出细线；两者都要从同一基准定位。"],
["S2","测量与标记","detail","Study Pack p.31 · 3.2","外卡钳量得的“尺寸”通常如何转成数值？","先把开口转移到钢尺或其他刻度量具上比较读数；外卡钳本身用于比较/转移，不直接显示尺寸。"],
["S2","测量与标记","detail","Study Pack p.31–32 · 3.2","如果内卡钳两脚不与孔径方向对齐，会有什么后果？","测得的不是孔的最大内径，比较尺寸会偏小；应让两脚跨过孔中心并轻微摆动找最大读数。"],
["S2","测量与标记","core","Study Pack p.31–32 · 3.2","Jenny 卡钳的直脚为何要贴靠基准边？","直脚建立基准，弯脚或划线尖端转移固定偏距，才能划出与边平行的线。"],
["S2","测量与标记","detail","Study Pack p.31–32 · 3.2","用 Jenny 卡钳找圆钢中心时，关键是让工具完成什么？","借直脚和可调划线脚从外缘转移位置/划线，利用相交定位找截面中心；先确认工件稳定。"],
["S2","测量与标记","detail","Study Pack p.31–32 · 3.2","弹簧分规和 Jenny 卡钳的典型标记任务有何区别？","弹簧分规主要划圆和转移距离；Jenny 卡钳常用于沿基准边划平行线或定位中心。"],
["S2","测量与标记","core","Study Pack p.32 · 3.2","千分尺的棘轮在测量时要达到什么目的？","让测量面以较一致的接触力贴合工件，减少每次用力不同造成的读数变化。"],
["S2","测量与标记","detail","Study Pack p.32 · 3.2","测微器读数中，套筒与微分筒分别贡献哪部分？","套筒主刻度给出整毫米/半毫米，微分筒给出基准线对齐的细分读数；按量具刻度相加。"],
["S2","测量与标记","detail","Study Pack p.32 · 3.2","千分尺测量时工件倾斜夹在测量面之间会造成什么？","测量轴与工件尺寸方向不一致，接触位置可能偏斜，造成读数误差；应让测量面正确贴合。"],
["S2","测量与标记","detail","Study Pack p.32–33 · 3.2","闭合游标卡尺后显示不为零，该如何处理？","先清洁测量面并检查零位误差；不能直接把后续读数当真值，按仪器说明校正或记录零误差。"],
["S2","测量与标记","core","Study Pack p.32–33 · 3.2","游标卡尺的深度杆适合检查什么？","测量孔、槽或台阶的深度；量具底座应稳定贴在参考面上。"],
["S2","测量与标记","detail","Study Pack p.32–33 · 3.2","用游标卡尺测内径时，卡爪应如何摆放？","内测量爪伸入孔内并跨过中心，轻微调整到最大稳定读数，避免只测到弦长。"],
["S2","测量与标记","detail","Study Pack p.32–33 · 3.2","如何让游标卡尺测外径时不发生倾斜误差？","外测爪与工件轴线/被测面正确对正，轻触工件并保持卡尺方正，不以过大夹力挤压。"],
["S2","测量与标记","detail","Study Pack p.32–33 · 3.2","游标卡尺“主尺与游标读数相加”前要先找什么？","先读游标零线左侧的主尺数值，再找与主尺刻线重合的游标刻线，按量具分度换算并相加。"],
["S2","测量与标记","detail","Study Pack p.32–33 · 3.2","量具分辨率、准确度和精密度是否同义？","不是：分辨率是可显示的最小变化，准确度是接近真值程度，精密度是重复测量的一致程度。"],
["S2","测量与标记","core","Study Pack p.31–33 · 3.2","尺寸公差很小而工具刻度太粗时会怎样？","量具无法可靠分辨所需尺寸差；应选择分辨率和准确度适合公差的量具，并遵循校准要求。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","测量前清洁工件和量具接触面有什么作用？","油污、切屑或毛刺会改变接触位置和间隙，造成错误读数或损伤量具。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","为什么要在相同基准面上测量一组相关尺寸？","保持尺寸链一致，避免不同起点的误差叠加，便于复核图样和加工结果。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","放样前图样的尺寸单位和比例要核实什么？","确认尺寸单位、基准、图样比例和关键尺寸标注；以给定数值为准，不用缩放图纸猜尺寸。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","为什么不能只靠“看起来对齐”判断冲点位置？","视觉估计受视差和边缘形状影响；应用基准、量具和标记工具确定中心，冲点前再核对。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","重复测量时读数差别很大，优先检查哪些原因？","检查基准是否一致、工具零位/校准、测量方向和接触力、工件是否移动以及读数视角。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","为什么精密量具不宜随意用来划线或夹紧工件？","量具设计用于测量，侧向力和划擦可能损坏测量面或校准状态；用适合的划线/夹持工具完成工序。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","测量电缆路径时，为什么布尺比钢卷尺合适？","教材指出布尺可量取路径长度；钢卷尺不应在带电设备附近使用以免导电造成危险。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","怎样区分量具读数问题和工件尺寸问题？","先检查量具零位、校准和测法，再换合适量具重复测量并复核基准；不要修改工件来“修正”未查明的读数。"],
["S2","测量与标记","core","Study Pack p.31–33 · 3.2","钢尺分度是 0.5 mm，是否代表任何测量都能准确到 0.5 mm？","不是。分度只是刻度间隔；读数技巧、尺具校准、边缘和工件状态也影响准确度。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","外卡钳如何用于比较两个轴的直径？","把卡钳调到第一个轴的尺寸，再在第二个轴上比较是否松紧变化；必要时用刻度量具读出差值。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","Jenny 卡钳平行划线时，哪个部位沿边移动？","直脚靠着工件基准边滑动，弯脚/划线尖端在设定偏距处划线。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","测量孔深时深度杆未垂直于底面会怎样？","深度读数可能偏大或偏小；量具底座贴平参考面，深度杆沿孔轴向到达底部。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","将读数记录为“约 10 mm”对精密加工有什么不足？","缺少实际分辨率、单位和必要精度信息；应按任务要求记录数值、单位及量具/测量条件。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","测量后锁住千分尺主轴能帮助什么操作？","在需转移尺寸或离开工件读值时，锁定可减少主轴移动；按仪器结构操作，不用锁紧力压迫工件。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","直角尺翻转检查中，两条线不重合说明什么？","工具的内外角或直边可能不准确，也可能基准面不直；先确认基准，再停用/标识失准工具。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","基准边有毛刺时直接放样会造成什么？","工具不能稳定贴合，整个尺寸位置会偏移；先检查并按程序处理毛刺，不把毛刺当作测量基准。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","多个孔位都从前一个孔量距离，误差为何容易累积？","每次定位误差会叠加到后续尺寸；从统一基准逐个定位可减少累积误差。"],
["S2","测量与标记","core","Study Pack p.31–33 · 3.2","图纸未给出的加工尺寸应怎样处理？","停止猜测，向主管/设计人员澄清并按批准图样或现场变更执行；不能自行按比例估算关键尺寸。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","划线前为何要确认工件固定并有足够支撑？","防止工件移动、滚动或振动造成偏线，也减少手靠近锐边/工具的风险。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","重复测量时为何应避免在工件不同温度状态下比较？","材料和量具会热胀冷缩，温差可能改变尺寸；精密比较要按任务条件稳定温度。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","划线染料、墨水或记号笔选用时注意什么？","选不会影响后续加工、涂层或粘接的标记介质，并遵循材料和现场程序。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","放样完成后怎样做一道低成本的防错复核？","切割/钻孔前重新核对基准、尺寸、方向、孔位和保留/去除区域，并与图样交叉检查。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","工件在台钳中夹持得离钳口太远有什么问题？","悬伸过大易振动、弯曲或夹持点松动；尽量靠近钳口支撑并评估工件形状。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","圆管放在平口台钳中直接夹紧有哪些风险？","圆形表面容易滚动或滑出，也可能被压变形；采用适合的 V 形支撑/软钳口并确保稳定。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","切割线紧贴台钳钳口布置有何好处？","缩短悬伸，减少切割时振动和弯曲，让锯缝更容易保持直线。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","夹持软金属或成品表面时如何避免压伤？","选用软钳口/保护垫并适度夹紧；保护材料不得使工件松动或失去定位。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","钢锯锯条张力不足可能造成什么结果？","锯条容易偏斜、扭曲或卡住，锯缝不直并增加断条风险；按工具要求安装和张紧。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","钢锯锯条张得过紧同样危险吗？","是。过度张紧会增加锯条/弓架负荷并可能导致断裂；只按工具允许的张力安装。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","手锯切到薄片边缘时，怎样减少齿刃挂住？","选择适合薄材料的细齿锯条并让足够多齿同时接触，起锯时轻压控制。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","手锯转弯时为什么不应强行侧扭锯条？","锯条主要承受沿锯切方向的载荷，侧扭会使其卡住、变形或断裂；应调整工件/切割路径。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","锯齿数与材料厚度的匹配原则是什么？","薄料用较细齿、厚料用较粗齿，保证多齿同时接触；教材表格用于课程记忆，实际还看锯条和材料。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","钢锯条的回程应怎样施力？","回程放松压力，减少齿刃磨损和锯条受力；动力钢锯的行程规则依其机构和说明书。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","切割中锯缝开始偏斜，应该继续加力纠正吗？","不应猛压或扭锯条；停下检查夹持、锯条方向和工件位置，再按安全方法重新导向。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","冷凿作业前锤击端变成蘑菇头，为什么要停用？","蘑菇状金属可能崩裂并飞溅伤人；应按工具维护程序修整或更换，并使用护目防护。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","冷凿切削角为何要随材料硬度改变？","角度要兼顾刃口强度和切入能力；教材给出软、硬金属的不同角度示例，实际依凿具/材料要求。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","冷凿切下的碎片为何需要控制飞出方向？","金属碎片可能高速弹出并伤及操作者或旁人；用护目/面部防护并安排安全的作业方向。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","剪薄金属板前为何要确认薄板剪的左右/直线类型？","不同刃口形状适合不同方向和曲线；选错会使剪切路径难控制并可能扭曲板材。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","薄板剪剪到行程末端时为什么不能强扭工具？","强扭可能损伤剪刃、扭曲薄板或造成失控；选择合适剪型并按制造商方法切割。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","薄板切下的废料为什么要立即妥善放置？","锋利边缘可能割伤或刺穿手套、衣物；清理时避免徒手抓取并按废料程序处置。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","螺栓剪的杠杆原理怎样帮助切断金属杆？","长手柄放大手施力在刃口处的夹切力，适合规定范围内的杆材/紧固件；不可超出工具额定能力。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","使用螺栓剪时为什么不能用套管加长手柄？","加长会产生超过设计值的力，可能损坏工具或导致刃口/工件突然失控。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","台钳的丝杆负责把哪种动作转成夹紧动作？","旋转手柄带动丝杆轴向移动活动钳口，把工件夹在固定与活动钳口之间。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","台钳上夹持工件时，为什么要避免用延长杆猛拧手柄？","过大夹力会损坏丝杆、钳口或工件，甚至使铸件破裂；用正常手力达到稳固即可。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","工作台虎钳与机用虎钳的定位要求有何不同？","机用虎钳固定在机床工作台上，并要让工件相对刀具/钻头稳定定位；手工虎钳不替代机床夹具要求。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","锉刀齿纹由粗到细怎样排列？","Bastard-cut 较粗，second-cut 居中，smooth-cut 最细；按去料量和表面质量选用。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","锉刀柄松动或开裂时继续锉削有什么危险？","尖柄可能刺穿手掌或柄部脱落导致失控；先安装完好的匹配锉柄再使用。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","锉削时工件离钳口太远会影响什么？","工件可能振动或弯曲，锉刀更难控制且表面易不平；减小悬伸并稳定夹持。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","锉刀堵齿后为何不宜继续用力压锉？","切屑会划伤工件、堵塞继续加重并降低切削效果；先用锉刷清理齿槽。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","回程时对锉刀施加重压会造成什么？","会加快锉齿磨损并降低控制；按受控工作行程施力，回程减压。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","用砂布包在锉刀上抛光工件时应注意什么？","按受控锉削方向使用并防止手指靠近边缘；砂布不能掩盖尺寸不合格。"],
["S2","夹持与切割","core","Study Pack p.34–37 · 3.3","Safe-edge file 的安全边具体保护什么？","一侧无齿，可锉一个表面而减少损伤相邻面/已加工表面的风险。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","何时优先选择半圆锉而不是平锉？","需要处理凹面、圆孔边或平面兼具时，半圆截面更容易贴合曲面。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","木锉和普通金属锉的齿形用途有何差别？","木锉/rasp 的独立粗齿适合木材快速去料；普通锉齿适合相应金属表面加工。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","工件锯切后留下毛刺，为什么还要去毛刺？","毛刺会割伤人员、妨碍配合或损伤绝缘/电缆；按图样和任务要求处理切边。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","更换锯条或锉柄前应先做什么？","停止工具、解除可能的机械张力并确保工件稳定；使用适合工具完成更换。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","对较薄工件进行锯切时，怎样降低振动？","缩短悬伸、夹紧并在必要时使用合适背衬/支撑，避免施加过大切削力。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","锯切路线应在夹持前先检查什么？","确认锯条不会碰到台钳、夹具或工作台，并安排工件方向和切口位置。"],
["S2","夹持与切割","detail","Study Pack p.34–37 · 3.3","锉刀适合用来替代什么精密工序？","锉削可去除少量材料和修整表面，但不能替代严格尺寸/公差所需的机加工和量测复核。"],
["S2","钣金与紧固","core","Study Pack p.38–39 · 3.4","薄板金属定义中的厚度边界是教材课程定义还是所有行业通用定义？","这是本课程教材对 sheet metal 的定义；其他行业/标准可能按不同厚度分类，应注明来源语境。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","黑色金属和有色金属各举一类教材例子？","低碳钢/不锈钢属于含铁材料示例；铜、铝、黄铜等为有色材料示例。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","薄板表面的粉末涂层或镀层可能承担什么功能？","帮助防腐蚀、增加耐磨或化学耐受；加工后切边/孔位可能破坏涂层，按工艺修复防护。"],
["S2","钣金与紧固","core","Study Pack p.38–39 · 3.4","抽芯铆钉为何适合只能接触工件一侧的连接？","铆钉可从单侧放入并用拉铆工具形成背面锁固，不需要从连接背面扶住螺母。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","抽芯铆钉施工前要确认哪几项匹配？","孔径、夹持范围、铆钉材质/长度和被连接材料厚度，均按产品数据与工件要求核对。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","自攻螺钉与机螺纹螺钉的成牙方式有什么区别？","自攻螺钉在合适导孔中切出/成形配合螺纹；机螺钉通常与已攻丝孔或螺母配合。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","Drive screw 在教材例子中怎样固定电机铭牌？","敲入式螺钉将标签固定到较厚金属框架等位置；按指定工具和基材条件使用。"],
["S2","钣金与紧固","core","Study Pack p.38–39 · 3.4","薄板槽盒的内/外斜接为什么要先规划折叠余量？","切口和搭接舌片决定折后边缘是否闭合；按教材放样步骤预留搭接尺寸。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","制作槽盒斜接时为什么要先标出基准线和转折点？","基准线控制切口和折线位置，避免左右侧长度不一致或折出错误角度。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","槽盒 T 形接头的切口边缘为什么要去毛刺？","锋利边会割伤、损伤电缆/绝缘或妨碍折边贴合；处理后再折叠、固定和检查。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","板材厚度增加时，折弯/剪切所需工具选择会怎样变化？","较厚或强度更高材料通常需要能力更高的工具和夹持；不能仅靠加大手力。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","薄板剪切留下裂口或波浪边通常提示什么？","剪型/刀口不合适、工件支撑不足或操作方向控制不佳；检查材料和工具后再加工。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","钢板连接选择铆接还是螺纹紧固时先比较什么？","是否需要拆卸、背面能否接近、载荷与振动、材料厚度、腐蚀兼容性和外观要求。"],
["S2","钣金与紧固","core","Study Pack p.38–39 · 3.4","薄板上的机螺钉连接要避免什么螺纹问题？","避免有效啮合过短或薄板螺纹剥脱；根据板厚和连接设计选用螺母/铆螺母等方案。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","切下薄板废料时怎样减少割伤？","戴适合的防割手套并用工具夹持/移除废料，切边朝向受控区域，及时放入指定容器。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","板金加工后应核对哪几项而不只看外观？","尺寸、孔位、方正度、毛刺、折边/接头贴合及涂层受损情况；按图样和验收要求复核。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","中心冲和划针在钻孔定位中各做什么？","划针标出位置/圆周，中心冲在圆心形成凹点；凹点帮助钻尖定位，减少初始滑移。"],
  ["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","教材给出的定位冲和见证冲尖端角度分别是多少？","教材示例为定位中心冲约 60°、较尖的见证冲约 40°。将其作为本教材的工具示例记忆，实际使用还要看冲头设计和工件。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","工件表面没有冲点时，钻头起始阶段更容易发生什么？","钻尖可能沿表面滑动，造成孔位偏移或刮伤；先按材料和工序做定位标记。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","钻削中的 swarf 指什么？","钻孔产生的切屑，包括小片和细长卷屑；应让其安全排出，不用手在旋转钻头附近清理。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","麻花钻 flutes 需要同时提供哪两种作用？","形成切削刃并提供排屑通道，把切屑从孔底带出。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","麻花钻的 helix 对切削有什么帮助？","螺旋形几何形成正前角并引导切屑沿槽排出；正确方向和锋利度影响切削质量。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","碳钢钻头和 HSS 钻头的课程材料用途有什么差别？","教材把碳钢钻头列为常见木材用途、HSS 列为金属用途；遵照钻头标识和制造商材料适用范围。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","HSS 相对碳钢钻头的教材优势是什么？","较能承受较高工作温度；这不表示可以忽略转速、切削条件或冷却要求。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","钴钻头、硬质合金钻头和涂层钻头能否只凭名称互换？","不能；基材、涂层/刃口、工件和设备条件决定适用性，查看产品规格而非只看名称。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","用千分尺测钻头直径时，应量哪两个位置？","量钻头两侧切削刃外缘之间的最大直径，避开螺旋槽底部。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","钻头规和千分尺在现场各适合什么用途？","钻头规便于识别/核对钻头尺寸；千分尺可精确测量外径，选择取决于所需精度。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","教材的转速经验值为何不能替代设备/刀具说明？","经验值按课程给定直径范围概括，材料、钻头材质、润滑和机床能力会改变推荐转速。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","工件材料相同，钻头直径增加时转速通常应如何调整？","通常降低转速以控制切削速度、发热和扭矩；具体数值查工具/刀具数据。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","钻头开始冒烟或发蓝通常说明什么？","可能过热、转速/进给不适、刀刃钝或润滑不足；立即停止并按程序检查，不继续强钻。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","钻孔时只有摩擦声却不出屑，应检查什么？","检查钻头锋利度、旋转方向、材料/钻头适配、进给和转速；停止后再检查，避免徒手触碰热刃。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","钻头排屑槽被堵时不宜继续增加进给力，为什么？","堵屑会增加摩擦和扭矩，可能卡钻、折断钻头或使工件转动；停止并安全清屑。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","中心冲点太浅可能导致什么？","钻尖无法稳定定位，起钻时更容易跑偏；按工件材质做足够但不过度的定位冲点。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","中心冲点太深对薄板有什么潜在影响？","可能使板材凹陷、变形或留下不合格痕迹；根据厚度控制冲击力度并使用支撑。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","在薄板上使用扁木工钻头是否合适？","该钻头为木材大孔设计；金属薄板应使用适合金属和孔径的工具，避免挂住/撕裂。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","Auger bit 为什么能被螺纹尖端拉入木材？","螺纹尖端咬入木料并引导钻头进给；教材用于较大直径木框孔，需按钻具说明和夹持条件使用。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","使用扁木工钻头贯穿木料时，出口侧为什么容易崩裂？","刃口在出口处可能撕扯未支撑的木纤维；可按任务使用背衬或从两侧完成孔。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","石工钻头切削端常用什么材料？","教材列举碳化钨硬质合金头与螺旋钢杆；核对钻头标识是否适用于基材。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","教材列出的石工钻头适用哪些基材？","砖、砌块、石材、采石砖和混凝土等；具体型号按基材硬度和钻机功能选择。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","为什么石工钻孔通常采用较低转速并配合冲击？","冲击动作帮助硬质合金头破碎矿物基材；低速有助于控制工具，仍须按钻头说明。"],
["S2","钻头与钻孔","detail","Study Pack p.40 · 3.5","普通旋转钻头误用于混凝土时可能出现什么？","进展慢、钻头过热或损伤；使用基材和工具相匹配的石工钻头与钻机模式。"],
["S2","钻头与钻孔","core","Study Pack p.40 · 3.5","Fly cutter 与 hole saw 的切孔方式有何区别？","孔锯以圆筒锯齿切出环形孔；飞刀由设定半径的切削刀具旋转成孔，低速并特别关注防护。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","Trammel 除划圆外教材还指出什么用途？","可用于从片材切割圆形垫片；旋转尖端/刀刃暴露，须控制位置和防护。"],
["S2","钻头与钻孔","detail","Study Pack p.41 · 3.5","孔锯导向钻的作用是什么？","先定位并引导锯筒沿孔中心切入，减少偏移；确保导向钻牢固且与锯筒组合正确。"],
["S2","钻头与钻孔","detail","Study Pack p.41 · 3.5","孔锯在即将切穿工件时为什么要减小进给？","出口侧支撑减弱，突然贯穿可能撕裂材料、卡住或造成反作用；控制贯穿阶段。"],
["S2","钻头与钻孔","core","Study Pack p.41 · 3.5","从工件两侧用孔锯完成孔的顺序是什么？","先从一侧钻至接近贯穿，停下并从另一侧对准导孔完成切割，以减小出口撕裂。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","使用飞刀/划圆器前要特别确认哪项？","刀具半径、夹紧和防护区域；它有外露切削刀具，必须按设备说明使用并限制人员靠近。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻大孔时为何要考虑先导孔或分级加工？","降低切削负荷并帮助定位，尤其是大直径/薄板作业；采用与工具制造商建议一致的工艺。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻孔时长卷屑缠绕钻头怎么办？","停止并隔离旋转工具后，用合适工具清除切屑；绝不在钻头旋转时用手拉扯。"],
["S2","钻头与钻孔","core","Study Pack p.40–41 · 3.5","钻头磨损或刃口崩缺时继续工作会影响什么？","孔位/孔径和表面质量变差，发热与卡钻风险增加；更换/修磨后再使用。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻头装入夹头后，为什么要取下夹头钥匙再开机？","钥匙可能被甩出造成撞击伤；启动前清点并移除所有夹头调整工具。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻床工作台调整完成后，为什么要再次确认锁紧？","未锁紧的台面可能在钻削力下移动，导致孔位偏移或夹具/工件失控。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻削圆形工件为什么需要 V 形块或专用夹具？","圆件容易滚动或被钻头带转，V 形支承可帮助定位；仍应可靠夹紧。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻孔前为什么要检查工件背面有无障碍物？","防止钻头穿出时损伤台面、夹具、隐藏线路或人员；确认安全余量和工作区域。"],
["S2","钻头与钻孔","core","Study Pack p.40–41 · 3.5","钻孔产生的金属屑应怎样清除？","先停机并待旋转停止，用刷子/专用工具清理；不徒手扫屑或靠近旋转部件。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","为什么钻孔切屑可能很烫？","切削摩擦把能量转化为热，金属屑会灼伤皮肤；使用适合的防护并等待冷却。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻孔产生的粉尘或碎屑如何影响周围人员？","可能进入眼睛/呼吸道或污染设备；用护目、适当抽排/屏蔽和受控清洁降低暴露。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","为什么不可戴松垂手套靠近旋转钻床主轴？","手套可能被旋转件卷入；遵循设备风险控制，手远离旋转部件并按规定使用夹具。"],
["S2","钻头与钻孔","core","Study Pack p.40–41 · 3.5","钻孔完成后留下锐利毛刺，后续装配前应做什么？","按工艺去毛刺并检查孔口，防止割伤、损伤线缆/绝缘或影响零件配合。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻孔后孔中心偏移，最有价值的复盘顺序是什么？","检查基准和冲点、工件夹持、钻头锋利度/偏摆、钻机垂直度及进给控制，找出根因再返工。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻头突然卡死时为什么不应强行扭转电钻脱困？","反作用扭矩可能伤腕、损坏夹头或使工件旋转；停止并按设备说明安全释放。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","夹头夹持面有切屑会造成什么问题？","钻头可能偏心、夹持不牢或打滑；断电后清洁夹头并确认钻头正确夹紧。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","同一孔要穿过不同材料层时，为什么应在加工前识别层次？","材料改变会影响钻头、转速、进给和出口支撑；先确认层次可避免钻错或损伤隐藏部件。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻孔前用中心冲定位后，为什么还要检查冲点与尺寸线关系？","冲点本身可能偏离标记；开钻前复核孔中心和边距，避免加工后才发现位置错误。"],
["S2","钻头与钻孔","core","Study Pack p.40–41 · 3.5","钻头直径 4.25 mm 的课程转速划分应归在哪一侧？","教材规则把 4.25 mm 本身归入“4.25 mm 或更大”的一侧；实际转速仍查设备/刀具资料。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","孔锯直径与材料不匹配可能发生什么？","切削负荷、转速和孔径不匹配，可能卡住、过热或造成不合格孔；按工件与工具规格选择。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","为何不能在旋转孔锯上清除木屑塞？","旋转锯齿会夹卷手指或工具；先停机并等待停止，再按制造商方法取出木芯。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","中心冲和球头锤作业时，工件如何放置更安全？","工件应稳定支撑、冲点位置可见，锤击方向远离手指和旁人；使用护目镜控制飞屑。"],
["S2","钻头与钻孔","detail","Study Pack p.40–41 · 3.5","钻孔时遇到钢筋或隐藏金属层应如何做？","停止加工，确认图纸/扫描结果并向主管澄清；不强行穿透，也不擅自改变结构件。"],
["S2","攻丝与套丝","core","Study Pack p.42 · 3.6","攻丝（tapping）形成的是工件哪一侧的螺纹？","在孔的内表面切出内螺纹，以便与螺栓/螺钉配合。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","丝锥的槽如何形成切削刃并处理切屑？","槽之间的刃口切削材料，槽容纳并排出切屑；堵屑会增加卡滞和断锥风险。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","丝锥方柄与丝锥扳手的配合目的是什么？","方柄把扭矩传给丝锥扳手，使其能受控旋转；避免用不匹配工具夹伤丝锥。"],
["S2","攻丝与套丝","core","Study Pack p.42 · 3.6","攻丝底孔过小会给丝锥带来什么影响？","需要切除的材料过多，扭矩增大，丝锥易卡住/断裂且螺纹质量变差。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","攻丝底孔过大通常会怎样影响内螺纹？","剩余材料不足，螺纹啮合深度/强度可能降低；底孔尺寸须按螺纹规格表选。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","M10 × 1.5 与 M10 × 1.25 的底孔为何不同？","公称直径相同但螺距不同，牙深和切除材料量不同；按完整规格查教材表。"],
["S2","攻丝与套丝","core","Study Pack p.42 · 3.6","用“公称直径减螺距”估算底孔时，结果代表什么？","这是课程中 60° 公制螺纹的常用近似攻丝钻头直径，不代替精确表格或具体螺纹要求。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","钻好攻丝底孔后，为什么要检查孔口毛刺？","毛刺会妨碍丝锥对正和起牙，也可能影响成品螺纹入口；按要求倒角/去毛刺。"],
["S2","攻丝与套丝","core","Study Pack p.42 · 3.6","攻丝开始时如何减少丝锥偏斜？","让丝锥轴线与孔轴线对正，可用工程师直角尺辅助检查；起牙阶段轻而均匀地施力。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","攻丝中丝锥突然变紧，应如何处理？","停止施力，按工艺适度反转断屑并检查对正、排屑、润滑和底孔；不可猛扭硬拧。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","盲孔攻丝为何要特别留意孔底余量？","丝锥前端不一定切出完整牙，切屑也需空间；孔深和目标有效螺纹长度应按图样/工具选择。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","通孔和盲孔选择丝锥时考虑什么？","盲孔需要接近孔底完成目标螺纹，通孔要考虑丝锥穿出空间；按丝锥类型与加工要求选择。"],
["S2","攻丝与套丝","core","Study Pack p.42 · 3.6","锥形丝锥、中间丝锥和塞规/底锥的常见使用顺序是什么？","从容易起牙的锥形丝锥开始，再继续切削，最后用塞规/底锥完成盲孔深处；遵循套装说明。"],
["S2","攻丝与套丝","detail","Study Pack p.42 · 3.6","教材为什么说 plug tap 不用于起始攻丝？","它用于盲孔底部形成更完整螺纹，起始导入能力较弱；先用适合起牙的丝锥。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","攻丝时每隔一段旋转反向的目的是什么？","折断切屑、减少槽内堵塞和螺纹撕裂；教材示例约四分之一圈反转，实际依工件/工具要求。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","软材料攻丝为什么也需要适用的切削润滑剂？","润滑可改善切削、降低摩擦和撕裂风险；润滑剂需与工件材料及后续清洁兼容。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","丝锥切削刃已钝时继续攻丝会出现什么？","扭矩上升、螺纹粗糙、发热或卡断风险增加；检查刃口并更换合适丝锥。"],
["S2","攻丝与套丝","core","Study Pack p.42–43 · 3.6","套丝加工的是工件哪一侧的螺纹？","在杆/轴外表面形成外螺纹，以便与螺母或内螺纹孔配合。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","板牙的 stock 有什么作用？","夹持板牙并提供可控旋转扭矩，使其沿工件轴线切出外螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","给杆端倒角为什么有助于板牙起牙？","形成导入面，让板牙较容易同轴咬入第一圈螺纹，减少偏斜和乱牙。"],
["S2","攻丝与套丝","core","Study Pack p.43 · 3.6","板牙开始切削时为什么必须保持与杆件垂直？","起牙歪斜会形成斜螺纹，螺母难以旋入并可能损伤螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","分体/可调板牙的调节螺钉控制什么？","控制切入深度和切削量，可逐步切到目标尺寸；不能一次过度切削。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","为什么按钮板牙第一刀通常不先调到最终尺寸？","较小的初始切削更易起牙和控制，随后逐步调整到完整螺纹尺寸。"],
["S2","攻丝与套丝","core","Study Pack p.43 · 3.6","固定尺寸 die nut 与可调板牙的用途差异是什么？","固定 die nut 主要清理/修复已有螺纹或检查螺纹；可调板牙用于按需要切制外螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","修复生锈螺纹时为什么用 die nut 而不是强行拧螺母？","die nut 可清理已有牙型；硬拧螺母可能交叉咬合或进一步损伤螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","套丝时切屑堵住板牙，应如何处置？","停止并受控反转/退出工具，清除切屑并检查润滑和对正；避免持续增加扭矩。"],
["S2","攻丝与套丝","detail","Study Pack p.43 · 3.6","用板牙加工杆件前为什么要可靠支撑工件？","避免杆件转动、弯曲或偏摆，使螺纹同轴并保护操作者。"],
["S2","攻丝与套丝","core","Study Pack p.42–43 · 3.6","内螺纹和外螺纹分别由哪种工具加工？","丝锥加工孔内螺纹；板牙加工杆件外螺纹。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","怎样检查新加工的外螺纹而不损坏工件？","清理螺纹后用正确规格的螺母/量规轻旋检查；不要用扳手强迫通过阻滞点。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","为什么螺纹规格相同公称直径仍需核对螺距？","粗牙与细牙的牙距不同，底孔与配套件也不同；只看外径会选错工具。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","取出断螺栓前钻导孔，需要注意哪些定位问题？","孔要尽量沿断件中心并与轴线同心；偏心可能损伤原有内螺纹，必要时交由有经验人员处理。"],
["S2","攻丝与套丝","core","Study Pack p.42–43 · 3.6","断螺栓取出器为什么不宜施加过大扭矩？","取出器通常较硬而脆，过载可能折断在螺栓内，使后续加工更困难。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","断螺栓取出器的反向旋转如何帮助拆件？","先在断件中心形成导孔，再将取出器按指定方式咬入并反向旋转，逐步松开断件。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","攻丝完成后如何验证螺纹而不损坏工件？","去除切屑，目视检查牙型，并用合适配套紧固件/螺纹量规轻柔检查啮合。"],
["S2","攻丝与套丝","detail","Study Pack p.42–43 · 3.6","为什么不能用不确定规格的丝锥在孔里“试着找牙”？","可能交叉起牙、损伤工具或工件；先读标识、查规格并确认底孔尺寸。"],
["S2","电动工具","core","Study Pack p.44 · 3.7","教材要求使用电动工具前检查什么电气安全标识？","确认有符合课程要求且在规定检查周期内的电气测试标签；教材给出的周期是课程记忆点，现场法规/程序可能更新。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","为什么检查标签不能替代使用前的外观检查？","标签记录既往检查，不保证工具此刻无损；仍需检查线缆、插头、外壳、开关和附件。"],
["S2","电动工具","core","Study Pack p.44 · 3.7","冲击钻的三种模式通常分别是什么？","普通旋转钻孔、仅锤击，以及旋转加锤击；具体模式名称和用途按设备说明识别。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","在砌体中选择冲击钻的旋转加锤击模式，目的是什么？","旋转切削与轴向冲击共同帮助钻入砌体；使用匹配的石工钻头和适当转速。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","冲击钻“仅锤击”模式是否适合一般麻花钻孔？","不适合一般旋转切削孔；选错模式可能损坏钻头、工件或工具，先核对材料和说明书。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","教材列出冲击钻的每分钟冲击数，属于哪类信息？","是设备能力示例，不是每种钻头/基材的通用设置；以具体工具铭牌和制造商资料为准。"],
["S2","电动工具","core","Study Pack p.44 · 3.7","可调离合电动螺丝刀如何减少紧固件损伤？","离合器达到设定扭矩后打滑/脱开，帮助控制紧固力；设置需匹配紧固件、材料和工序。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","电动螺丝刀离合器设得过高可能出现什么？","螺钉过拧、螺纹滑牙、工件破损或批头打滑；先在试件上验证合适设置。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","热风枪在课程列举的电气工作中有什么用途？","用于热缩材料收缩等受控加热任务；注意热表面、邻近可燃物和材料耐温。"],
["S2","电动工具","detail","Study Pack p.44 · 3.7","热风枪的温度范围为何不等于工件可承受温度？","出风温度与工件实际温升不同，距离、时间和材料都会影响结果；按产品说明控制加热。"],
["S2","电动工具","core","Study Pack p.44–45 · 3.7","Nibbler（电动咬口机）适合什么薄板切割形状？","适合在薄金属板上作直线和曲线切割；确认材料厚度与设备能力相符。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","使用 nibbler 时切屑为什么需要单独收集？","工具会产生小金属冲屑，可能飞溅、割伤或进入设备；使用防护并清理收集。"],
["S2","电动工具","core","Study Pack p.44–45 · 3.7","立式钻床的三种主要进给/定位部件是什么？","主轴/钻夹头负责旋转刀具，进给手柄控制下行，工作台支撑并定位工件。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","立式钻床工作台高度或角度调整后必须做什么？","锁紧工作台并复核孔位、刀具与工件间隙，防止钻削中台面移动。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","为什么立式钻床上工件必须用虎钳或夹具固定？","钻头可能咬住工件并使其旋转；手扶工件无法抵抗反作用扭矩。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","钻床台面上的垫木/背衬有什么作用？","保护工作台和钻头出口，并减少穿透时材料撕裂；背衬不能替代工件夹紧。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","在钻床旋转时用手套清屑为何危险？","手套或衣物可能卷入主轴/钻头；停机并待完全停止后，用刷子或专用工具清屑。"],
["S2","电动工具","core","Study Pack p.44–45 · 3.7","长发、首饰和宽松衣物在钻床附近有什么危险？","可能被旋转主轴、钻头或工件卷入；按设备风险控制束发、移除首饰并穿合身衣物。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","立式钻床换钻头或调整夹头前需要做什么？","关机并隔离电源，等待旋转部件停稳；确认夹头钥匙已移除后再启动。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","为什么钻床上不能戴着夹头钥匙试转？","启动时钥匙可能高速飞出，造成严重撞击伤；钥匙只在调整时使用并立即取下。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","钻床切削中工件开始转动，操作者应做什么？","立即停机并隔离，不能用手抓住旋转工件；重新设计夹持后再继续。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","为什么不能在钻床上用手扶着小型工件钻孔？","小工件容易被钻头带转或抛出；用适合夹具固定并保持手远离切削区。"],
["S2","电动工具","core","Study Pack p.44–45 · 3.7","台式/立式钻床与手电钻相比，优势在哪里？","固定机床可提供稳定支撑和较一致的垂直进给，适合重复/精确钻孔，但需要可靠夹持和设置。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","钻床进给过快会造成什么？","切削负荷和热量增大、刀具卡住/折断或工件变形；进给应与材料、钻头和机床匹配。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","在钻床上钻通孔时怎样保护台面？","设置合适背衬并确认钻头穿透路径，不让钻头直接切入台面或夹具。"],
["S2","电动工具","detail","Study Pack p.44–45 · 3.7","钻床工作区的金属屑应何时处理？","每道工序停机并待部件停止后清理，避免切屑堆积干扰定位或进入运动部件。"],
["S2","电动工具","core","Study Pack p.45 · 3.7","砂轮机磨削前为什么要做教材所述的 ring test？","敲击检查砂轮是否可能有裂纹；异常声音可能提示损伤，按制造商方法执行且不使用可疑砂轮。"],
["S2","电动工具","detail","Study Pack p.45 · 3.7","ring test 通过能否保证砂轮绝对安全？","不能；它只是检查方法之一，仍需核对砂轮标识、额定转速、外观、安装和防护罩。"],
["S2","电动工具","core","Study Pack p.45–46 · 3.7","砂轮机工作托架需要怎样调整？","教材示例要求托架接近砂轮工作面且略高于中心；具体间隙以设备说明和当前安全程序为准。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","工作托架离砂轮太远会带来什么风险？","工件可能被卷入间隙、卡住或弹出；停机后按设备要求调整托架间隙。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","为什么不能用砂轮侧面磨削？","砂轮可能只按圆周磨削设计，侧向载荷会使其破裂；除非砂轮明确额定侧磨并获准。"],
["S2","电动工具","core","Study Pack p.45–46 · 3.7","教材为何警告不要在普通砂轮上磨铜、铝等软材料？","软金属容易堵塞砂轮磨粒间隙，改变磨削性能并引发过热/危险；按砂轮材料用途选择工具。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","砂轮表面磨损或不方正时，dressing 的作用是什么？","修整砂轮工作面、恢复形状并露出新的磨粒；只能由受训人员按工具说明操作。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","为什么启动砂轮机时不要站在砂轮正前方？","若砂轮有隐蔽裂纹或装配问题，启动初期破裂碎片可能沿旋转平面飞出。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","砂轮更换后首次启动应采取什么防护姿态？","按设备程序安装防护罩并保持人员避开砂轮旋转平面；由受训人员按制造商要求试运行。"],
["S2","电动工具","core","Study Pack p.45–46 · 3.7","角磨机作业前应核对磨片/切割片的哪些信息？","用途、材料适用性、直径、额定转速、损伤和安装方向；磨片额定值不能低于工具要求。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","角磨机切割片能否用于侧向磨削？","通常不能，切割片设计承受圆周切削；侧向受力可能破裂，遵循片材标识。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","角磨机放下前为什么要等磨片完全停止？","仍旋转的磨片可能碰到工作台/物体、移动工具或造成割伤；松开开关后保持握持直至停止。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","角磨机护罩的方向为什么要朝向操作者与旁人之间？","让护罩尽量阻挡碎片和火花飞向人员；依制造商安装并确保不妨碍正常控制。"],
["S2","电动工具","core","Study Pack p.44–46 · 3.7","电动工具的延长线、插头或外壳发现损坏，应怎样处理？","立即停止使用并标识/隔离，交由授权人员检查维修或报废；不能用胶带掩盖缺陷继续作业。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","为什么电动工具必须使用与环境匹配的电源保护？","施工环境可能潮湿、受损或机械风险高；保护配置应遵循现场电气程序和现行法规。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","电动工具发生异常振动、火花或异味时，正确反应是什么？","停止并断开电源，标记异常并报告；不带故障继续工作或自行拆修。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","更换电动工具附件前为什么要隔离电源？","避免误触开关导致工具意外启动，尤其是更换钻头、磨片或锯片时。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","砂轮机火花方向应如何纳入作业布置？","让火花远离人员、可燃物、电缆和敏感设备，并检查附近是否需设置屏障/监火。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","磨削时工件温度过高会带来什么后果？","可能灼伤操作者、改变材料性能或引燃邻近物；按工序控制接触时间并采取安全冷却方式。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","使用热风枪给热缩材料加热，如何避免损伤邻近绝缘？","控制距离、移动速度和温度，遮护敏感部件并监测收缩效果；先核对材料额定温度。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","用 nibbler 切割薄板时，为什么要控制废料出口？","冲屑可能飞出并进入设备或伤及旁人；佩戴护目装备、控制方向并清除切屑。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","工具标签上的转速与附件额定转速不匹配时怎么办？","不安装或使用该附件；先选择转速等级兼容的附件并按制造商数据确认。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","电动工具完成检查后，如何保护检查状态不被破坏？","规范收纳、避免线缆拉扯/潮湿和跌落；再次使用前仍做目视检查。"],
["S2","通用手工具","core","Study Pack p.47 · 3.8","组合钳为什么不能默认当作压接钳？","普通组合钳的钳口未按端子压接模具设计，压接形状/压力不可控；只用明确设计用于该端子的工具。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","哪一种组合钳例外可以压接端子？","具有专门压接模具并明确标注适用端子的组合工具；仍按端子与线径规格使用。"],
["S2","通用手工具","core","Study Pack p.47 · 3.8","斜口钳为何比普通钳子更适合剪切导体？","切刃延伸至工具前端，能把手柄作用力集中到切口处；选择与导体材质/截面相配的钳具。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","剪导线时为什么不能用侧切钳剪超出额定能力的硬件？","刃口可能崩损，线材反弹或工具失控；核对线材与工具规格，使用合适剪具。"],
["S2","通用手工具","core","Study Pack p.47 · 3.8","教材列举的两类剥线工具是什么？","手动/可调剥线钳和自动剥线工具；选择适合导体尺寸与绝缘类型的型号。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","剥线刀口设定过深会损伤什么？","可能刻伤或切断导体股线，降低有效截面积和机械强度；按线径设置并检查导体。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","剥线后导体出现缺口或断股是否可直接端接？","不应默认可用；缺口会削弱导体并影响接触，停止并按工艺切除重做/报告。"],
["S2","通用手工具","core","Study Pack p.47 · 3.8","电缆剪的刃口几何为何适合剪软电缆？","弧形/剪切刃逐步切入并支撑电缆，减少压扁；只剪工具额定范围内的电缆。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","扳手与螺丝刀都能“施力”，为什么不能相互替代？","两者受力形状和紧固件接口不同，错用会滑脱、损坏紧固件并伤手。"],
["S2","通用手工具","core","Study Pack p.47–48 · 3.8","开口扳手为什么只接触六角螺母相对的两面？","开口只夹持两平面，受力不当或规格不合可能使螺母圆角；选正确尺寸并保持贴合。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","开口扳手头部约 15° 偏置有什么便利？","翻转扳手可在狭窄空间改变重新咬合的角度，方便分段转动螺母。"],
["S2","通用手工具","core","Study Pack p.48 · 3.8","活动扳手使用时，受力方向应靠近哪个钳口？","让主要载荷落在固定钳口一侧，降低活动钳口张开或滑脱风险；仍按工具结构规范使用。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","活动扳手间隙过大有什么后果？","扳口容易滑过螺母平面，圆角紧固件并可能打伤手；先调紧并确认规格合适。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","活动扳手能否用作锤子或加长杆？","不能；冲击或额外杠杆会损伤工具并造成失控，应用专用锤子/长度合适的扳手。"],
["S2","通用手工具","core","Study Pack p.48 · 3.8","Multigrips 适合处理哪类工件？","可调钳口可夹持圆形/非六角件，例如教材提到的金属导管配件；保护表面并避免过度夹压。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","夹持镀铬或装饰表面时怎样减少钳痕？","使用适合的保护垫/软钳口，调整到可靠夹持而不压伤；必要时选择专用扳手。"],
["S2","通用手工具","core","Study Pack p.48 · 3.8","Vice grips（锁紧钳）与普通钳的功能区别是什么？","锁紧钳可调节并锁定夹持位置，适合暂时夹持/固定；不能代替额定夹具或受控扭矩工具。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","锁紧钳释放机构的学习重点是什么？","夹紧后仍需能受控解锁，释放时注意弹开夹口和夹伤手指；按工具说明操作。"],
["S2","通用手工具","core","Study Pack p.48–49 · 3.8","Allen key 的 AF 尺寸指什么？","Across flats，即内六角扳手两相对平面之间的尺寸；必须匹配螺钉内六角规格。"],
["S2","通用手工具","detail","Study Pack p.48–49 · 3.8","内六角扳手未完全插入螺钉孔会造成什么？","接触面积不足，易打滑并损伤内六角孔或扳手；清除孔内污物并完全插入。"],
["S2","通用手工具","detail","Study Pack p.48–49 · 3.8","螺钉头内六角已经滑圆时，继续用原规格扳手会怎样？","扳手会继续打滑并扩大损坏；停止并选择合适取出方案，避免盲目增加力矩。"],
["S2","通用手工具","core","Study Pack p.49 · 3.8","两臂拉马和三臂拉马用于拆卸什么？","从轴上拆卸压配/就位的轴承、齿轮等部件；拉爪对称抓牢并沿轴线施力。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","使用拉马时，顶丝应对准什么位置？","对准轴端中心/设计受力点，使拉力沿轴线，避免侧向偏载和部件歪斜。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","拉马的爪没有均匀抓住部件会有什么危险？","拉力偏心可能使爪滑脱、部件弹出或轴/齿轮损坏；重新定位并设置防护。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","拉马难以拆下轴承时，教材允许怎样辅助？","教材提到适当加热可帮助拆卸；仅由受训人员按材料、设备和热作程序评估实施。"],
["S2","通用手工具","core","Study Pack p.49 · 3.8","Rawhide mallet（生皮锤）为何适合电机绕组装配？","软质锤头可辅助放入预成形线圈或整形，减少对金属表面的硬冲击。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","球头锤的圆球端主要用于什么加工？","教材指出用于金属成形/锤击塑形；选择适当锤头和支撑，避免损伤精密表面。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","羊角锤在教材中与电气工作哪类紧固有关？","用于敲打电缆卡钉和相应固定件；确认基材、固定件和周边隐藏设施后再作业。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","工具手柄松动、油污或裂纹时为什么要停用？","可能造成握持失控、滑脱或柄头分离伤人；标识并维修/更换后再使用。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","工具规格以 AF、线径或端子范围标识时，应怎样选？","按紧固件/导体实际规格和制造商范围选择，不能用“差不多”尺寸强行适配。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","为什么切割工具需要保持锋利？","钝刃需要更大力、容易滑脱或压坏材料；维护和更换按工具程序执行。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","用钳子旋拧螺母代替扳手有什么风险？","钳口可能损伤螺母表面且容易滑脱；用与紧固件匹配的扳手。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","钳子剪切导体时，切口附近应如何安排手指？","手指避开刃口与导体回弹路径，保持工件稳定；佩戴适当眼部防护。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","拆卸重型轴上部件前为什么要支撑被拆件？","部件松脱后可能突然下落或弹出；支撑能控制重量和位移，保护人员及零件。"],
["S2","通用手工具","core","Study Pack p.47–49 · 3.8","为什么工具应按用途归类并在作业后检查？","便于选对工具、及时发现损坏并减少误用；检查结果影响后续作业安全和质量。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","拉马或扳手受力时，操作者站位要避开什么方向？","避开可能滑脱/弹出的运动路径，保持平衡并使用合适防护；不把身体置于受力线上。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","手工具不能达到目标效果时，正确的升级方式是什么？","暂停并重新评估任务，选额定能力合适的工具/夹具或请有经验人员协助，而不是延长手柄硬撬。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","砂轮出现裂纹、缺口或异常振动时应怎么办？","停止使用并按程序隔离/标识，由合格人员检查或更换；不尝试“试磨”确认是否安全。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","砂轮机防护罩缺失或松动时能否开机？","不能；停止使用并修复/更换防护后再按程序检查。"],
["S2","电动工具","detail","Study Pack p.45–46 · 3.7","角磨机切割时工件和切割片应如何稳定？","使用适合的夹持支撑，使切片不夹缝且操作者能保持受控姿势；不手持小工件切割。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","为什么不能把热风枪刚用完就放在工作台上？","喷嘴和加热元件仍可能高温，接触可点燃物或灼伤人员；置于规定耐热支架并等待冷却。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","电动工具的电气检查周期应从哪里确认？","课程教材给出检查标签示例，但实际周期依当前法规、场地政策和工具类别；遵从现行要求。"],
["S2","电动工具","detail","Study Pack p.44–46 · 3.7","电动工具电源线穿过作业区时应怎样布置？","避开锐边、热源、积水、车辆和绊倒路径；需要时采用批准的支撑/保护方式。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","组合钳宽扁钳口和切刃分别适合什么操作？","宽扁端夹持/扭转裸导体，切刃用于剪切；实际用途和导体尺寸以工具设计为准。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","剥线工具的自动调节机制能否免去成品检查？","不能；仍应检查绝缘是否完整剥离、导体是否缺股/刻伤以及长度是否合适。"],
["S2","通用手工具","detail","Study Pack p.47 · 3.8","电缆压接工具与端子规格为什么必须成套匹配？","模具、端子和导体范围共同决定压接形状与压力；不匹配可能造成高电阻或机械失效。"],
["S2","通用手工具","core","Study Pack p.47 · 3.8","压接完成后能否只看外观判定连接可靠？","外观是检查的一部分，还要核对压痕位置/模具标记并按工艺做拉力或其他规定验证。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","多功能钳夹持圆形导管配件时如何避免滑脱？","选择合适钳口开度，稳定夹持并避免施加偏斜力；装饰表面应使用保护措施。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","双头开口扳手翻面能改变什么？","偏置头部翻转后可在狭小位置获得不同的重新咬合角度。"],
["S2","通用手工具","detail","Study Pack p.48 · 3.8","螺母卡在狭窄位置，选择棘轮/套筒工具时先核对什么？","套筒尺寸和深度、可用摆动空间、驱动方头与紧固件状态；避免套筒歪斜受力。"],
["S2","通用手工具","detail","Study Pack p.48–49 · 3.8","使用锁紧钳拆卸时为什么要避免夹住易变形薄壁管？","钳口夹紧力可能压扁管壁或损伤表面；改用匹配管件的扳手或专用工具。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","拉马对准部件后仍需检查什么？","拉爪是否均匀受力、顶丝是否同轴、部件是否有支撑以及周围是否设防护。"],
["S2","通用手工具","detail","Study Pack p.49 · 3.8","加热辅助拆轴承为什么需要额外控制？","高温会造成灼伤、材料损伤或点燃油脂/溶剂；需有热作风险评估和受训人员操作。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","绝缘螺丝刀外层有裂纹时可以继续用在电气设备上吗？","不能把有缺陷的绝缘工具当作防护；退出使用并更换符合任务要求的工具。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","螺丝刀刀口尺寸与螺钉槽不匹配会造成什么？","接触不足导致打滑、槽口损坏或伤手；选择匹配的刀头并保持轴线对正。"],
["S2","拆卸与环境","core","Study Pack p.49–50 · 3.8","拆卸作业开始前第一步应确定什么？","明确拆卸目的、范围、顺序和设备状态，并识别所有危险能源与可能影响人员的部件。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸机械设备前如何控制残余机械能？","识别重力、弹簧、旋转惯性和夹持力，按程序释放或机械支撑并验证稳定。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸前为什么要确认气动和液压系统已卸压？","管路可能储存压力，断开接头时会喷射流体或驱动部件；隔离、卸压并验证零能量。"],
["S2","拆卸与环境","core","Study Pack p.49–50 · 3.8","拆卸计划如何降低重新装配时的错误？","按可追溯顺序标记、记录连接和零件位置，保存紧固件并记录损坏/缺件。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","为什么拆卸电气部件前要先确认导线和端子身份？","防止复装时错接；按批准图纸标识并记录，不能只依靠线色或记忆。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸顺序为什么要考虑零件重量和支撑点？","失去连接后部件可能突然下落、倾倒或夹住人员；先设置额定支撑并规划吊运。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","装配被拆设备后，教材要求结果还应能怎样处理？","装配完成的结果应能够测试/验证；不能只凭零件已装回判断功能和安全合格。"],
["S2","拆卸与环境","core","Study Pack p.49–50 · 3.8","拆卸与装配的过程关系是什么？","装配通常是拆卸的逆过程，但复装仍要核对损件、清洁、紧固和功能验证，不能机械倒放步骤。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","报废电气/电子设备为什么不能混入普通废料？","材料可能含污染物且可回收部件不同；分类可支持安全去污、再利用、回收或合规处置。"],
["S2","拆卸与环境","detail","Study Pack p.50 · 3.8","教材所述不透水工作区域用于什么环境管理？","用于去污、拆解和准备处置的作业，限制液体/污染物渗入地面并便于回收处置。"],
["S2","拆卸与环境","detail","Study Pack p.50 · 3.8","拆解产生的电缆、零件和清洗液应如何管理？","分类收集并防止泄漏/扩散，优先评估再用、回收和合规处置；遵从场地废弃物程序。"],
["S2","拆卸与环境","detail","Study Pack p.50 · 3.8","为什么减少能源和材料浪费也是电气作业能力的一部分？","设备和材料全生命周期会产生环境影响；计划采购、维护、复用和回收可减少资源消耗。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸中发现图纸与实物连接不一致时应如何做？","停止相关拆卸，记录差异并向主管确认最新设计/变更；不凭猜测继续断开。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸中发现未知液体或粉尘时应如何做？","暂停作业、避免接触和扩散，按危险物质程序隔离并报告，确认性质后再处置。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸后的零件怎样标记才能支持复装追溯？","标明设备/位置、方向、连接关系和拆卸顺序；标签需耐受现场环境且不会损伤部件。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","工具、夹具和作业人员怎样纳入拆卸步骤规划？","确认每一步需要的工具/支撑、人员配合和通信方式，确保拆下部件可被稳定控制。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","废弃物回收前为什么要先去污或分离？","油污、化学品或危险材料可能污染可回收物并危害处理人员；按材料和法规分别管理。"],
["S2","拆卸与环境","detail","Study Pack p.49–50 · 3.8","拆卸完成后工作区交接前要检查什么？","确认能源状态、散落件/废料、临时支撑、标记记录及设备封存/防护状态符合程序。"],
["S2","焊接与钎焊","core","Study Pack p.50–51 · 3.9","软钎焊和硬钎焊最基本的区别是什么？","填料金属熔化温度不同；教材以低于 427 °C 的软钎焊和约 593–871 °C 的硬钎焊作课程分类。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","软钎焊时母材是否应熔化？","不应；填料金属熔化并润湿/流入接头，母材保持未熔。"],
["S2","焊接与钎焊","core","Study Pack p.50–51 · 3.9","助焊剂在软钎焊中的主要作用是什么？","帮助去除/控制氧化物并改善焊料对接头表面的润湿；选用适配电子/电气用途的助焊剂。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","为什么应加热待连接的母材而不是只熔焊料？","热的母材使填料金属接触后融化并润湿接合面，有助于焊料进入接头间隙。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","焊料在接头上成团而不铺展，可能说明什么？","表面可能有氧化/污染、温度不足或助焊剂不合适；停止并检查清洁、加热和材料兼容性。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","焊料靠什么作用进入紧密接头间隙？","毛细作用将熔融填料吸入清洁且适当间隙的接合面。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","软钎焊前清洁导体表面有什么作用？","去除油污和氧化层，帮助焊料润湿；按工艺清洁并避免再次污染。"],
["S2","焊接与钎焊","core","Study Pack p.50–51 · 3.9","教材建议焊接接头完成后如何冷却？","自然冷却；用湿布骤冷可能在接头形成应力并导致后续失效。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","接头冷却后为什么要处理残留助焊剂？","残留物可能腐蚀或污染接头；教材建议冷却后用湿布清除残余助焊剂，遵从材料说明。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","软钎焊烟气控制的基本原则是什么？","在通风良好/局部抽排条件下作业，避免吸入烟气；具体防护依助焊剂安全数据和现场程序。"],
["S2","焊接与钎焊","detail","Study Pack p.50–51 · 3.9","焊接时热源和可燃物之间需要做什么？","移除或屏蔽可燃物并检查火花/热量可能到达的区域，必要时按热作程序设置监火。"],
["S2","焊接与钎焊","core","Study Pack p.51 · 3.9","硬钎焊时填料金属与母材熔点的关系是什么？","填料熔化并流入接头，但温度低于母材熔点，母材本体不熔化。"],
["S2","焊接与钎焊","detail","Study Pack p.51 · 3.9","为什么硬钎焊要先让火焰加热母材？","加热接合区域后填料可被母材热量熔化并流动；直接烧填料可能导致润湿和接头质量不佳。"],
["S2","焊接与钎焊","detail","Study Pack p.51 · 3.9","硬钎焊后的光滑 fillet 表示什么？","填料金属在接头边缘形成的圆滑过渡；外观需结合润湿、接头设计和检验要求判断质量。"],
["S2","焊接与钎焊","detail","Study Pack p.51 · 3.9","教材提到的硬钎焊填料可用于连接哪些代表性材料？","可用于铜/铜合金、工程材料、硬质合金和不锈钢等示例；具体填料必须匹配母材。"],
["S2","焊接与钎焊","detail","Study Pack p.51 · 3.9","焊炬燃气系统作业前要核对什么？","气瓶、调压器、软管、接头、泄漏状态、点火程序和通风，遵从热作/燃气设备要求。"],
["S2","焊接与钎焊","core","Study Pack p.51–52 · 3.9","MIG 焊中电压主要影响什么焊接特性？","影响电弧/熔池热量和熔深趋势；具体设定须与送丝速度、材料厚度和设备工艺配合。"],
["S2","焊接与钎焊","detail","Study Pack p.51–52 · 3.9","MIG 焊送丝速度为何不能脱离电压单独调？","两者共同决定电弧与熔敷状态；不匹配会导致飞溅、熔深不足或焊缝形状不良。"],
["S2","焊接与钎焊","detail","Study Pack p.51–52 · 3.9","薄板焊接教材倾向什么焊池状态？","教材示例倾向较冷的焊池以降低烧穿风险；真实参数按工艺规程/设备数据调整。"],
["S2","焊接与钎焊","detail","Study Pack p.51–52 · 3.9","较厚板材为什么可能需要较热焊池？","需要足够熔深和熔合；不能只依厚度直觉设定，按批准焊接工艺和设备参数操作。"],
["S2","焊接与钎焊","detail","Study Pack p.51–52 · 3.9","MIG、TIG 和电弧焊名称相近，复习时应分别辨认什么？","区分电极/填料供给方式和保护方式；教材列举 MIG、TIG 与电弧焊为不同工艺。"],
["S2","焊接与钎焊","detail","Study Pack p.50–52 · 3.9","焊接/钎焊作业后为什么还需检查接头？","确认接头连续、无明显孔隙/污染、机械稳定且符合图纸与验收要求；必要时做规定测试。"],
["S2","焊接与钎焊","detail","Study Pack p.50–52 · 3.9","焊接作业废料和助焊剂包装应如何处理？","按化学品和金属废料分类收集，避免污染排水/工作区并按场地环境程序处置。"],
["S2","焊接与钎焊","detail","Study Pack p.50–52 · 3.9","焊接时手部、眼睛和呼吸防护应如何决定？","依据工艺、烟气、飞溅、热辐射和安全数据评估，使用适配 PPE 与通风；PPE 不替代工程控制。"],
["S2","焊接与钎焊","detail","Study Pack p.50–52 · 3.9","发现焊炬软管泄漏或接头损坏应怎么办？","停止作业、关闭/隔离气源并按程序报告维修；不点火试漏或继续操作。"],
["S2","焊接与钎焊","core","Study Pack p.50–52 · 3.9","软钎焊、硬钎焊与熔焊在母材状态上的区别是什么？","钎焊利用填料连接且母材不熔；熔焊会使母材接合区域熔化，工艺控制不同。"],
["S2","焊接与钎焊","detail","Study Pack p.50–52 · 3.9","课程温度界限用于判断工艺时，还需确认什么？","确认教材定义、填料熔点和母材熔点的关系；数值是课程分类，不是具体工艺参数。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","读数时尺具移动或基准边改变，结果为什么不可靠？","测量起点和工具位置不一致会引入系统偏差；重新建立基准并复测。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","划线与加工线的哪一侧作为保留尺寸，为什么要先约定？","锯缝会移除材料，未约定保留侧可能使成品尺寸变小；依图样确定切割侧。"],
["S2","测量与标记","detail","Study Pack p.31–33 · 3.2","划线尖端钝或弯曲会导致什么问题？","标记变宽或偏离预定位置，降低放样精度；检查并更换/修复工具。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","折弯槽盒前留下的搭接舌片承担什么作用？","用于覆盖并固定斜接/接头边缘，帮助形成连续连接；长度和切口按教材步骤与实际尺寸布置。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","槽盒外斜接和内斜接的放样为何要反向思考？","需要切除的面/背面不同；按接头方向规划 V 形切口和折叠面，避免成品角度反转。"],
["S2","钣金与紧固","detail","Study Pack p.38–39 · 3.4","冲孔或剪切后涂层在孔边受损，应关注什么？","裸露金属可能更易腐蚀；按材料系统和产品要求修复切边防护。"],
["S2","钣金与紧固","core","Study Pack p.38–39 · 3.4","薄板连接方式如何按“是否可拆”来初步筛选？","需要可拆维护时优先评估螺纹紧固；永久/单侧可达连接可考虑铆接等方式，仍需校核载荷和材料。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","工具的刀刃/钳口与工件不匹配，常见失效是什么？","工具滑脱、紧固件圆角、导体损伤或操作者失衡；停止并换用适配尺寸和用途的工具。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","切断导体后怎样检查斜口钳剪口质量？","确认切口整齐、导体未被压扁/拉散，钳刃无缺损；不合格时更换工具或重做导体端部。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","扳手施力时为什么应避免猛拉并让手处于紧固件下方？","工具滑脱会使手撞击边缘/结构；优先采用可控推力、稳定站姿并避开可能运动方向。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","轴承拉马拆卸时为何不能站在拉马轴线上？","受力件或工具失效时可能沿轴线弹出；设置防护并让身体避开弹射路径。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","手工具用完后如何降低下次使用时的误伤风险？","清洁、检查并放回指定位置，刃口/尖端做适当保护，损坏工具标识隔离。"],
["S2","通用手工具","core","Study Pack p.47–49 · 3.8","绝缘手工具能否代替电路隔离和无电验证？","不能；绝缘工具只是附加防护，仍须遵循授权隔离、验证和工作程序。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","剥线长度由什么决定而不应凭习惯固定？","端子剥线长度、导体插入深度及产品说明；剥得过长会露铜，过短会夹住绝缘。"],
["S2","通用手工具","detail","Study Pack p.47–49 · 3.8","使用扭矩工具后为什么要按说明回调/存放？","维持校准和弹簧机构状态；具体存放设定按工具制造商要求，不能任意调节。"],
["S3","固定件选择","core","S3课程材料 · 固定件选择","选择固定件前首先要识别什么？","基材类型与状态、被固定物、载荷方向/大小、环境暴露、可用安装空间和后续维护要求。"],
["S3","固定件选择","core","S3课程材料 · 固定件选择","fastener 与 fixing 在课程中的概念区别是什么？","Fastener 连接两个或多个部件；fixing 将设备或部件固定到基材/结构上。具体术语以课程上下文为准。"],
["S3","固定件选择","detail","S3课程材料 · 固定件选择","钉子固定木材时，为什么要关注接收木料的厚度和钉入长度？","固定能力取决于钉入接收材的有效长度；长度不足会降低握持力，过长则可能穿出或损伤另一侧。"],
["S3","固定件选择","detail","S3课程材料 · 固定件选择","为什么硬木可能需要预钻孔？","预钻导孔可降低劈裂风险，并帮助紧固件沿预定位置进入；孔径应依据紧固件和材料要求确定。"],
["S3","固定件选择","core","S3课程材料 · 砖石固定","砖石螺钉/锚固件的导孔应如何确定？","按产品指定的钻头直径、孔深、清孔和安装方式执行；不能把单一尺寸套用到所有基材和产品。"],
["S3","固定件选择","detail","S3课程材料 · 砖石固定","混凝土膨胀锚为什么不能过度拧紧？","过大膨胀力可能使锚栓、混凝土或砖石基材开裂/剥落，并降低实际承载。按制造商扭矩和边距要求安装。"],
["S3","固定件选择","core","S3课程材料 · 锚固件","塑料膨胀塞的握持力来自哪里？","螺钉旋入后使塞体在基材孔内膨胀，产生机械咬合/摩擦；适用性取决于基材、孔尺寸和产品额定值。"],
["S3","固定件选择","detail","S3课程材料 · 锚固件","chemical anchor（化学锚栓）依靠什么固定？","树脂胶粘剂在基材孔内固化，将螺杆/钢筋与基材粘结；孔洞清洁、基材状态、温度和固化时间都会影响结果。"],
["S3","固定件选择","detail","S3课程材料 · 锚固件","为什么化学锚孔洞的清洁步骤不能省？","粉尘和松散颗粒会妨碍树脂与孔壁粘结，使锚固性能无法达到产品设计值。"],
["S3","基材与载荷","core","S3课程材料 · 基材匹配","实心砖墙、空心砖和石膏板为什么不能使用同一种固定方案？","基材内部结构与可承载方式不同：实心材料可形成孔壁咬合，空腔材料需展开式/专用锚固，石膏板承载有限；须匹配产品与实际结构。"],
["S3","基材与载荷","core","S3课程材料 · 基材匹配","固定件标称载荷能否直接等同于现场安全工作载荷？","不能。额定值依赖规定的基材、安装、受力方向、边距、间距和安全系数；现场设计应使用产品数据及适用规范。"],
["S3","基材与载荷","detail","S3课程材料 · 基材匹配","固定件设计为什么要区分拉拔力和剪切力？","拉拔力沿固定件轴向把它拔出；剪切力横向作用，可能使固定件或基材剪断。实际连接可能同时承受两者。"],
["S3","基材与载荷","detail","S3课程材料 · 基材匹配","设备振动会给固定件带来什么额外考量？","重复载荷可能导致松动、疲劳或基材破坏；应采用适用于动载的产品、正确安装和定期检查。"],
["S3","基材与载荷","detail","S3课程材料 · 墙体支撑","石膏板上的重物为何优先固定到立柱或横档？","结构构件可提供比薄板面材更可靠的承载路径；仅依靠板材或轻型空腔锚可能不适合重载。"],
["S3","基材与载荷","detail","S3课程材料 · 墙体支撑","stud wall（立柱墙）的典型构成有哪些？","竖向立柱与顶板、底板组成框架，横档/nogging 可在立柱间提供额外支撑点。实际结构以现场和图纸为准。"],
["S3","基材与载荷","core","S3课程材料 · 支撑件","电缆梯架、线槽或设备支撑点如何布置才合理？","根据载荷、跨距、结构强度和产品数据布置支点，使载荷均匀传至可靠结构，避免局部过载或过大挠度。"],
["S3","基材与载荷","detail","S3课程材料 · 支撑件","为什么不能把支撑间距只按经验固定成一个数？","最大间距受产品类型、材料、载荷、安装方向、环境和规范要求影响；应查制造商资料和适用标准。"],
["S3","安装与检验","core","S3课程材料 · 安装质量","安装锚固件前要检查什么？","核对基材、隐藏服务、边距和间距；选择匹配钻头/孔深；检查工具和紧固件型号，再按说明安装。"],
["S3","安装与检验","detail","S3课程材料 · 安装质量","为什么固定件不能离混凝土边缘太近？","边缘附近膨胀或拉力容易造成混凝土劈裂、崩边；遵照具体产品规定的最小边距。"],
["S3","安装与检验","detail","S3课程材料 · 安装质量","安装后怎样进行合理的固定质量检查？","检查型号、位置、埋入/展开状态、紧固程度、基材裂损和设备稳定性；需要的拉拔测试应由合格人员按规定执行。"],
["S3","胶粘与胶带","core","S3课程材料 · Adhesives","adhesive force 与 cohesive force 有何区别？","黏附力使胶粘剂附着到被粘材料表面；内聚力是胶粘剂自身内部的结合强度。"],
["S3","胶粘与胶带","detail","S3课程材料 · Adhesives","双面胶带相较液态胶的常见优点是什么？","便于快速、干净地粘接，通常不需要混合或较长固化；承载能力和耐环境性仍应查产品数据。"],
["S3","胶粘与胶带","detail","S3课程材料 · Adhesives","环氧胶常以哪些性能见长？","固化后可提供较强粘结并适用于多种材料；性能受配比、表面处理、温湿度和固化时间影响。"],
["S3","胶粘与胶带","detail","S3课程材料 · Adhesives","使用胶粘剂要考虑哪些危险？","皮肤/眼睛接触、溶剂蒸气、可燃性、放热固化和误混合等；阅读 SDS、通风并使用规定 PPE。"],
["S3","胶粘与胶带","detail","S3课程材料 · Adhesives","self-amalgamating tape（自融带）通常如何形成密封？","拉伸包覆后相邻层逐渐融合为连续绝缘/密封层；按产品说明控制拉伸、搭接和覆盖范围。"],
["S3","遗产与环境","core","S3课程材料 · Heritage","改造遗产建筑时为什么不能只按普通施工方式处理？","建筑可能有受保护的历史、文化或结构价值；须先识别保护要求、取得授权并尽量减少不可逆改动。"],
["S3","遗产与环境","detail","S3课程材料 · Heritage","遗产工程开工前应查哪些信息？","保护清单/规划控制、业主要求、主管机关许可、既有图纸、材料特征和允许的改动范围。"],
["S3","遗产与环境","detail","S3课程材料 · Environment","胶粘剂、清洗剂和拆除废料为什么要分类管理？","可能含挥发性化学品、污染物或可回收材料；依 SDS 和当地环境规定储存、收集与处置。"],
["S3","固定件选择","core","S3课程材料 · Fixings","永久连接与可拆卸连接在选型时有什么差别？","需考虑是否需要后续拆卸、检查或更换；永久胶接/铆接和可拆卸螺纹连接的维护性不同。"],
["S3","固定件选择","detail","S3课程材料 · Fixings","为什么固定件选型要考虑载荷方向而不只看设备重量？","同一重量可产生拉力、剪力、弯矩或偏心力；连接和基材承受方式不同，需按组合载荷核对。"],
["S3","固定件选择","detail","S3课程材料 · Fixings","什么情况下自攻螺钉可能不适合直接承担设备载荷？","基材过薄、强度不足、振动明显或螺纹啮合长度不足时，螺纹可能滑脱或疲劳；应按产品额定条件设计。"],
["S3","固定件选择","detail","S3课程材料 · Fixings","drive screw（敲入式螺钉）属于哪类安装方式？","通过敲击使其进入材料形成固定，常用于适合该产品的薄板/构件；基材和用途按制造商资料确认。"],
["S3","基材与载荷","detail","S3课程材料 · Anchors","肘节式空腔锚的承载机制是什么？","插入空腔后展开或翻转，在板材背面形成较大支承面，将载荷分散到空腔板上；板材状态、厚度和产品规格仍有限制。"],
["S3","基材与载荷","detail","S3课程材料 · Anchors","近混凝土边缘安装锚固件有什么额外风险？","锚固膨胀和拉力可能使边缘崩裂；采用经评定适用于边缘位置的产品并核对边距、间距和基材强度。"],
["S3","基材与载荷","detail","S3课程材料 · Supports","为什么线槽、托盘和电缆支撑不能靠相邻管道承托？","每类服务应由适当结构支撑；借用其他管线可能造成载荷叠加、磨损或维护时失稳。"],
["S3","基材与载荷","detail","S3课程材料 · Cable ties","室外电缆扎带需要考虑什么性能？","紫外线、温度、湿度和化学环境会影响材料寿命；选用标明适合户外环境的产品。"],
["S3","胶粘与胶带","detail","S3课程材料 · Adhesives","胶接强度为什么依赖表面准备？","油污、锈蚀、粉尘或表面能不足会妨碍润湿和粘结；按胶粘剂产品说明清洁、粗化或底涂。"],
["S3","胶粘与胶带","detail","S3课程材料 · Adhesives","胶粘剂有哪些常见限制？","固化时间、温度/湿度敏感、剥离强度、长期老化、难以拆卸以及对表面处理的要求。"],
["S3","遗产与环境","detail","S3课程材料 · Heritage","heritage（遗产）资产除了建筑还可能包括什么？","文化景观、考古遗址、物件、传统实践和社区价值等；具体保护对象以登记/法规定义为准。"],
["S3","遗产与环境","core","S3课程材料 · Heritage","在遗产资产上施工前最重要的流程是什么？","识别保护状态和许可条件，与业主及主管机构沟通，形成获批的施工方法后再动工。"],
["S3","固定件选择","core","Study Pack p.57 · 4.1","固定件选择时教材列出的四类比较因素是什么？","功能、材料/产品属性（刚度、强度、寿命）、载荷大小与方向、安装工艺；还要兼顾外观要求。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","固定连接承受的力为什么要区分大小和方向？","相同设备重量可形成不同拉力、剪力或弯矩；固定件和基材的承载方式会随载荷方向改变。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","连接是永久还是需要拆卸，会如何影响固定件选择？","焊接/铆接等偏永久；螺钉/螺栓可便于维护拆装。还需检查强度、可达性和维护频率。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","为什么 fastener 和 fixing 在教材里既有区别又有重叠？","教材先区分连接部件与固定到结构的用途，随后说明日常术语常混用；按上下文理解，不把词义当成产品性能。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","螺钉、螺栓、铆钉、销和焊接分别代表哪类连接方案？","它们是不同的连接器件/工艺；选择时考虑可拆性、基材、载荷、安装工具和检查需求。"],
["S3","固定件选择","core","Study Pack p.57 · 4.1","钉子斜钉（skew nailing）对木材连接有何帮助？","斜向钉入可增加连接件在木材中的约束/抗拔效果；钉入方向和边距按工件及课程图示控制。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","硬木预钻导孔的教材比例值有什么适用边界？","教材给出约为钉径 0.8 倍的课程示例；真实木种、钉型和连接要求变化时应查设计/制造商资料。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","木材钉接时钉长过短或过长分别有什么问题？","过短会降低进入接收材的握持长度；过长可能穿透另一侧、损伤隐藏物或造成危险。"],
["S3","固定件选择","detail","Study Pack p.57 · 4.1","螺钉头型选择时要考虑哪种工具接口匹配？","螺钉头槽型/驱动头需与批头形状和尺寸匹配，避免打滑、损坏槽口或伤手。"],
["S3","固定件选择","core","Study Pack p.57–58 · 4.1","砖石螺钉安装为什么必须按产品规格钻导孔？","孔径和孔深决定螺纹咬合、安装扭矩与基材状态；不同产品/砖石条件不可套用单一数值。"],
["S3","固定件选择","detail","Study Pack p.57–58 · 4.1","砖石孔钻得太大可能导致什么？","螺纹/膨胀部件无法按设计抓持孔壁，固定能力下降；按产品数据选择钻头并检查磨损。"],
["S3","固定件选择","detail","Study Pack p.58 · 4.1","塑料膨胀塞的安装顺序包含哪些要点？","定位、用匹配石工钻头钻至所需孔深、清孔、把塞体正确装入，再配套螺钉固定；依产品指示。"],
["S3","固定件选择","detail","Study Pack p.58 · 4.1","塑料膨胀塞没有完全进入孔中会影响什么？","螺钉受力和塞体膨胀可能不均，配件不能贴合基材；不要强敲损坏，应检查孔深和塞体规格。"],
["S3","固定件选择","core","Study Pack p.58 · 4.1","套筒膨胀锚靠什么机制抓住孔壁？","紧固螺母/法兰使套筒扩张并压紧孔壁，形成机械锚固；孔径和安装扭矩需匹配产品。"],
["S3","固定件选择","detail","Study Pack p.58 · 4.1","安装套筒锚时为什么要防止锚体在孔内跟转？","套筒无法相对孔壁正确扩张，锚固可能失效；按产品要求准备孔并使用适当安装方法。"],
["S3","固定件选择","detail","Study Pack p.58 · 4.1","套筒锚的孔深略大于锚长在教材示例里用于什么？","给锚端/扩张结构留出安装空间；实际孔深和边距需按锚栓产品说明，而非照抄教材图例。"],
["S3","固定件选择","detail","Study Pack p.58 · 4.1","为什么安装膨胀锚前要确认基材没有裂缝或空洞？","缺陷会改变锚固区承载并可能扩展；应检查基材、边距和锚栓适用条件，必要时改设计。"],
["S3","固定件选择","core","Study Pack p.59 · 4.1","化学锚由哪些基本部分形成连接？","螺纹杆/钢筋、基材孔壁和经混合固化的树脂组成粘结锚固。"],
["S3","固定件选择","detail","Study Pack p.59 · 4.1","注入化学锚树脂时为什么要避免气泡/空腔？","空隙会减少有效粘结接触并使锚固表现不可靠；按产品规定注胶和植入顺序操作。"],
["S3","固定件选择","detail","Study Pack p.59 · 4.1","化学锚未达到规定固化时间就加载有什么风险？","树脂尚未形成设计粘结强度，锚杆移动会破坏粘结；等待时间取决于产品和温度。"],
["S3","固定件选择","detail","Study Pack p.59 · 4.1","化学锚树脂作业时哪些暴露需要控制？","蒸气吸入、皮肤和眼睛接触；读取安全数据表，使用规定 PPE 并保持适当通风。"],
["S3","固定件选择","detail","Study Pack p.59 · 4.1","化学锚孔洞清洁为什么对粘结至关重要？","粉尘/松散颗粒会隔开树脂与孔壁，降低粘结；用产品指定的刷孔、吹孔或清理步骤。"],
["S3","基材与载荷","core","Study Pack p.60 · 4.2","石膏板空腔锚如何把拉力传到板材背面？","锚翼或翻开构件在板背展开，增大受力区域；承载受板材状态、厚度、边距和产品限制。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","空腔锚的防旋齿起什么作用？","安装时咬住板面，防止锚体随螺钉旋转；需按产品要求开孔并压紧定位。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","选择空腔锚时为什么要核对墙板厚度范围？","锚翼展开位置和夹持厚度要匹配；板厚超出范围会使锚固不能正确锁紧。"],
["S3","基材与载荷","core","Study Pack p.60 · 4.2","Toggle anchor 与简单膨胀塞相比，适合何种基材结构？","Toggle 锚利用背面展开，在空腔墙/天花板后侧形成支承；仍要遵守产品额定载荷和安装方向。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","吊顶上的空腔锚为何不能直接沿用墙面承载值？","受力方向、板材弯曲和重力持续作用不同；教材提醒天花使用须按条件折减，设计应查产品数据。"],
["S3","基材与载荷","core","Study Pack p.60 · 4.2","比起单独依赖石膏板锚，横档（nogging）提供什么优势？","把设备载荷传到墙/顶的结构框架，通常可形成更可靠的支承；横档尺寸与固定按结构要求确定。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","安装重型设备时，为什么先寻找立柱或结构支撑？","结构支撑可把载荷传入墙体框架；面板本身的局部承载可能不足。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","立柱墙里的横档通常放在哪里、起什么作用？","横向装在立柱之间，提供额外固定面和刚度，便于安装设备/支撑。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","孔洞位置靠近石膏板边缘可能发生什么？","板边易破裂，锚固区和承载能力下降；按产品所需边距定位，必要时改用结构支撑。"],
["S3","基材与载荷","detail","Study Pack p.60 · 4.2","同一块墙板上多个锚点很近会有什么相互影响？","应力区可能重叠、板材局部压坏或撕裂；间距按锚具说明和结构条件校核。"],
["S3","固定件选择","core","Study Pack p.61 · 4.3","Powder-actuated tool（火药驱动紧固工具）的动力来源是什么？","使用受控火药/爆炸能量把钉销等紧固件打入钢材或混凝土等基材。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","谁可以操作火药驱动紧固工具？","教材要求操作人员经过培训、考试并取得认证操作卡；实际资格以当前法规和雇主要求为准。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","火药驱动工具为什么不能因“操作简单”就自行试用？","它具有高能量和射钉/穿透危险，需认证培训、设备检查、基材评估及安全区域控制。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","火药驱动钉在混凝土/钢材中使用前要先验证什么？","基材适用性、厚度/边距、隐藏服务、紧固件和药筒规格及设备额定要求；由合格操作员决定。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","火药驱动紧固可能造成哪些主要危险？","穿透/飞射物、反弹、噪声、粉尘、误击和基材破裂；设置隔离区、护目/听力防护并遵守操作程序。"],
["S3","固定件选择","core","Study Pack p.61 · 4.3","教材对膨胀气体式射钉工具和火药驱动工具如何区分？","教材指出膨胀气体式工具以扩张气体驱动，操作培训/要求与火药驱动系统不同；仍须遵守产品和场地规则。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","射钉进入基材后出现弯曲或未坐实，应怎样处理？","停止并由合格人员检查基材、功率和紧固件组合；不在失效钉旁盲目重复击发。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","火药驱动工具出现未击发药筒时，如何处置？","遵守制造商规定的等待、卸载和故障处理流程；不得立即打开或对准人员检查。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","射钉工具如何存放才能避免未授权使用？","锁定并将工具/药筒与紧固件按制造商要求安全存放，限制未受训人员接触。"],
["S3","固定件选择","detail","Study Pack p.61 · 4.3","紧固工具前检查墙内/基材另一侧有何必要？","紧固件可能穿透或造成背面碎片，伤害人员或击中管线/电缆；确认危险区和结构信息。"],
["S3","固定件选择","core","Study Pack p.61 · 4.3","火药驱动工具的认证卡意味着操作员还可忽略现场风险评估吗？","不能；资格只证明相应培训/考核，具体任务仍要评估基材、人员、设备和工作区风险。"],
["S3","基材与载荷","core","Study Pack p.62 · 4.3","Bolt 在教材定义中通常与什么配合使用？","螺栓是与螺母配合的螺纹紧固件；具体连接可能由接合件和受力条件决定。"],
["S3","基材与载荷","detail","Study Pack p.62 · 4.3","螺栓拧紧后，接合面上的主要夹紧作用是什么？","螺栓预紧力把连接部件压紧，使载荷可由接合面摩擦/连接结构传递；具体设计不能只按名称判断。"],
["S3","基材与载荷","detail","Study Pack p.62–63 · 4.3","教材列举的 flange bolt 有何可识别特征？","螺栓头下带一圈法兰/凸缘；选型仍须核对强度等级、材质与尺寸。"],
["S3","基材与载荷","detail","Study Pack p.62–63 · 4.3","shoulder bolt 的肩部适合什么运动连接？","肩部可作为精确配合的轴段，供部件滑动或转动；螺纹段不应被误作整个轴承面。"],
["S3","基材与载荷","detail","Study Pack p.62–63 · 4.3","square-neck bolt 的方颈有什么作用？","方颈可嵌入配合孔/槽并帮助防转，顶部可为圆顶或其他头型；需匹配工件孔形。"],
["S3","基材与载荷","detail","Study Pack p.62–63 · 4.3","lag bolt 与普通机螺栓在外观/安装上有什么区别？","教材将 lag bolt 描述为带尖端、螺钉式紧固件，按材料和产品要求旋入基材。"],
["S3","基材与载荷","core","Study Pack p.63 · 4.3","螺栓强度等级标记首位数字大致表示什么？","教材说明首位关联标称抗拉强度等级（以百 MPa 表示的系列）；具体性能须按标准标记表核实。"],
["S3","基材与载荷","detail","Study Pack p.63 · 4.3","螺栓强度等级标记的第二位数字与什么有关？","与材料达到永久伸长/屈服相关的强度比例有关；准确解释和性能值查对应标准。"],
["S3","基材与载荷","detail","Study Pack p.63 · 4.3","为什么不能把不同强度等级的螺栓随意替换？","强度、延性、预紧和连接设计可能不同；替换须经设计/主管批准并匹配螺母垫圈。"],
["S3","基材与载荷","detail","Study Pack p.63 · 4.3","机器螺栓的螺纹可以有哪些系列？","教材列出粗牙和细牙；规格需包含直径/螺距和等级，以确保配合正确。"],
["S3","基材与载荷","core","Study Pack p.64–65 · 4.3","轴键（key）怎样连接轴和轮毂？","键同时嵌入轴的键槽和轮毂键槽，阻止齿轮/皮带轮相对轴转动并传递转矩。"],
["S3","基材与载荷","detail","Study Pack p.64–65 · 4.3","Dowel pin（定位销）在装配中的核心作用是什么？","让部件精确定位并保持相对位置，便于重复拆装和对中；它与一般承载螺栓功能不同。"],
["S3","基材与载荷","detail","Study Pack p.64–65 · 4.3","Cotter pin（开口销）通常防止什么？","插入销孔后防止螺母/部件松脱、滑出或转离；按指定孔销尺寸和弯脚方式安装。"],
["S3","基材与载荷","detail","Study Pack p.64–65 · 4.3","Retaining ring（挡圈）适合控制哪类零件移动？","在轴或孔的槽内限制零件轴向移出；安装/拆卸需用合适的挡圈钳。"],
["S3","基材与载荷","detail","Study Pack p.64–65 · 4.3","垫圈放在螺母/螺栓头下可能提供什么作用？","分散接触压力、保护表面或帮助锁紧/定位，具体作用取决于垫圈类型。"],
["S3","基材与载荷","detail","Study Pack p.64–65 · 4.3","垫圈尺寸不匹配会导致什么？","接触面支承不足、边缘干涉或预紧力分布不当；选与紧固件和连接面匹配的垫圈。"],
["S3","基材与载荷","detail","Study Pack p.62–65 · 4.3","锚栓和普通螺栓的主要应用基材差别是什么？","锚栓用于把部件锚固到混凝土/砌体等基材；普通螺栓多通过螺母连接构件。产品应用须看认证数据。"],
["S3","基材与载荷","core","Study Pack p.65–66 · 4.4","固定件的“ultimate load”与静态载荷限值是同一指标吗？","不是。教材区分静载限值与极限静载荷；极限值不应直接当作允许工作载荷。"],
["S3","基材与载荷","detail","Study Pack p.65–66 · 4.4","教材为什么强调固定件额定载荷不等于基材承载？","额定值针对固定件，砖、混凝土、木材或板材的强度和状态还要单独评估。"],
["S3","基材与载荷","detail","Study Pack p.65–66 · 4.4","设备重量和墙体材料为什么是固定件选择的两个起点？","载荷决定需要承受的力，基材决定可用的锚固机制；还需继续校核受力、环境和安装条件。"],
["S3","基材与载荷","detail","Study Pack p.66 · 4.4","固定件的天气、老化和腐烂耐受性为何重要？","暴露环境会降低材料强度或使其失效；选耐腐蚀/耐候材料并与基材兼容。"],
["S3","基材与载荷","detail","Study Pack p.66–68 · 4.4","为什么表面安装的配电附件需要固定到 parent material？","载荷应传到可靠基材/结构，而不是只依赖薄饰面或松散覆层。"],
["S3","基材与载荷","core","Study Pack p.67–68 · 4.4","教材对表面附件的固定点数量给出什么最低提示？","教材总结提示至少两个固定点；实际数量、布置和承载按产品、结构及适用标准核验。"],
["S3","基材与载荷","detail","Study Pack p.67–68 · 4.4","室外电缆扎带为何要关注 UV resistance？","太阳紫外线会使不适用的聚合物老化脆化，扎带可能断裂；选择明确适合外用的规格。"],
["S3","基材与载荷","detail","Study Pack p.68 · 4.4","扎带收紧后为什么不能勒到电缆护套变形？","过紧可能压伤外护套/绝缘或产生磨损点；只收紧到可靠束缆/固定，避免损伤电缆。"],
["S3","基材与载荷","detail","Study Pack p.68 · 4.4","Velcro 型扎带与尼龙扎带在维护上有何区别？","钩环带可反复拆开调整；尼龙扎带通常是一次性束紧。选择按环境、负载和维护需要决定。"],
["S3","胶粘与胶带","core","Study Pack p.69 · 4.5","adhesive force 和 cohesive force 分别发生在哪里？","adhesive force 作用在不同材料的界面；cohesive force 是同一材料内部的内聚力。"],
["S3","胶粘与胶带","detail","Study Pack p.69 · 4.5","双面压敏胶带的 release liner 有什么作用？","储存时保护预涂胶层，安装时剥除后露出粘接面。"],
["S3","胶粘与胶带","core","Study Pack p.69 · 4.5","粘接表面有油、灰尘或松散涂层时会发生什么？","胶层无法充分接触稳定基材，粘接强度和耐久性下降；按产品规定清洁和表面处理。"],
["S3","胶粘与胶带","detail","Study Pack p.69–70 · 4.5","双面胶带的载荷分布特点有什么优势？","可沿较大接触面积均匀分布载荷，并可能缓冲振动/噪声和冲击；是否适用要看载荷与环境。"],
["S3","胶粘与胶带","detail","Study Pack p.69–70 · 4.5","为什么胶带/胶粘连接不适合所有需要后续维修的设备？","拆卸可能困难并损伤表面；设计时应把可维护性和更换需求纳入选择。"],
["S3","胶粘与胶带","core","Study Pack p.70 · 4.5","双组分环氧使用前最重要的混合控制是什么？","按规定比例充分混合树脂与固化剂；比例或混合不均会影响固化和最终性能。"],
["S3","胶粘与胶带","detail","Study Pack p.70 · 4.5","环氧胶达到初粘是否代表已经达到最大强度？","不是；初始固定和最终固化是不同阶段，按产品规定等待完全固化后再加载。"],
["S3","胶粘与胶带","detail","Study Pack p.70–71 · 4.5","服务温度升高为何可能降低某些胶接强度？","温度会影响聚合物和界面性能；确认胶粘剂工作温度范围及热循环条件。"],
["S3","胶粘与胶带","detail","Study Pack p.70–71 · 4.5","使用环氧树脂和固化剂时怎样避免暴露？","避免皮肤/眼睛接触和吸入蒸气，使用产品指定手套、护目和通风措施，并查安全数据表。"],
["S3","胶粘与胶带","core","Study Pack p.71 · 4.5","Anaerobic adhesive（厌氧胶）通常在什么条件下固化？","教材说明其在空气中保持液态，处于缺氧并接触金属离子时固化；常作螺纹锁固/密封用途。"],
["S3","胶粘与胶带","detail","Study Pack p.71 · 4.5","自融带与普通压敏胶带的成带机制有什么差异？","自融/自 amalgamating 带缠绕拉伸后层间融合形成连续包覆层，不依靠普通表面胶层粘住。"],
["S3","胶粘与胶带","detail","Study Pack p.71 · 4.5","自融带适用电缆接头时仍需核对哪些条件？","电压等级、绝缘系统、接头结构、环境和制造商施工要求；教材用途示例不构成所有接头的批准方案。"],
["S3","遗产与环境","core","Study Pack p.72–73 · 4.6","教材所说的 heritage asset 范围是否只有历史建筑？","还包括地点、遗址、物件、景观、地质、动植物和栖息地等文化/自然遗产要素。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","遗产场所施工前为什么要识别保护状态与审批要求？","未经批准的钻孔、拆除或布线可能破坏受保护材料；先与资产管理方确认允许方法和边界。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","电气改造中“保护建筑织体”希望减少什么？","尽量减少对原有建筑材料/构造的破坏，采用可行的保存、重复利用和可逆性方案。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","电气作业的环境管理可以通过哪些资源策略体现？","减少不必要能耗、重复使用材料、分类回收并妥善处置废物；按现场环境计划执行。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","采购电气材料时教材建议考虑什么生命周期信息？","关注材料/设备的制造方式、能耗、寿命和报废处置，优先考虑环境影响较低的可行选项。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","施工废物分类为什么要在作业计划阶段考虑？","可预先准备收集容器和去污区域，减少混装污染并提高复用/回收率。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","环境管理方案为什么需要定期监测和复核？","材料采购、废物和作业影响会变化；监测可发现控制失效并改进实践。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","在受保护区域发现未知遗物或敏感生境时，应如何做？","停止可能造成影响的作业、保护现场并通知主管/资产管理方，待授权评估后再继续。"],
["S3","遗产与环境","detail","Study Pack p.72–73 · 4.6","胶粘剂、溶剂和含污染物废料为什么要分类收集？","避免不相容化学品混合和环境释放，并让后续去污、回收或合规处置可追溯。"],
["S4","图纸与比例","core","原教材 Chapter 5 · Drawings","电气图纸最重要的沟通作用是什么？","用一致的符号、尺寸和注释传达设备位置、类型、数量及连接/控制关系，供不同施工人员共同理解。"],
["S4","图纸与比例","core","原教材 Chapter 5 · Scale drawings","比例 1:100 表示什么？图上 25 mm 对应实际多长？","图上 1 单位代表实际 100 同单位；图上 25 mm 对应实际 2500 mm，也就是 2.5 m。"],
["S4","图纸与比例","detail","原教材 Chapter 5 · Scale drawings","读图时为什么要先看标题栏、单位和比例？","避免用错版本、比例、单位或项目范围；量尺前要确认图纸是否按比例打印，关键尺寸优先看标注尺寸。"],
["S4","图纸与比例","core","原教材 Chapter 5 · Drawings","安装图（installation/layout diagram）主要表达什么？","设备在建筑中的相对位置及其控制/连接关系；不一定表示实际电缆的精确物理路径。"],
["S4","图纸与比例","core","原教材 Chapter 5 · Schedules","设备编号与 specification schedule（规格表）怎样配合？","安装图编号应与规格表逐项对应，规格表提供设备描述、型号或额定信息；两者需共同核对。"],
["S4","图纸与比例","detail","原教材 Chapter 5 · Drawing conventions","图上灯具与开关之间的虚线通常表示什么？","表示控制关联/回路逻辑，不应自动理解为电缆实际敷设路线；实际接线须看相应原理图和说明。"],
["S4","符号与布置","core","原教材 Chapter 5 · Symbols","为什么要使用标准化电气符号，而不是随手画图？","标准符号减少歧义，让施工、检修和协调人员能够一致识读；遇到不熟悉符号应查图例/标准。"],
["S4","符号与布置","detail","原教材 Chapter 5 · Site plans","site plan（总平面图）与 floor plan（平面图）分别重点表示什么？","总平面图表示建筑在场地中的位置及外部关系；平面图表示建筑内部房间、墙体和设备布置。"],
["S4","符号与布置","detail","原教材 Chapter 5 · Construction drawings","协调图纸为什么要结合其他建筑服务信息？","电气路径可能与结构、管道、空调和其他系统冲突；提前协调可避免返工、结构损伤和维护困难。"],
["S4","照明控制","core","原教材 Chapter 5 · Lighting circuits","one-way（单控）开关回路的基本逻辑是什么？","一个开关控制一个照明负载的通断；课程图示中开关应控制有源侧，具体端子接法按设备图和当地规则确认。"],
["S4","照明控制","core","原教材 Chapter 5 · Lighting circuits","two-way（双控）照明能实现什么功能？","两个控制位置都可以改变同一照明负载的状态，常见于走廊或楼梯两端。"],
["S4","照明控制","core","原教材 Chapter 5 · Lighting circuits","三个或更多位置控制一盏灯，常见开关组合是什么？","两端使用 two-way 开关，中间位置加入 intermediate（中途/交叉）开关；连接方式按回路图确认。"],
["S4","照明控制","detail","原教材 Chapter 5 · Lighting circuits","双控开关的 COM 与切换端子为什么不能混淆？","COM 是公共端，另两个端子在不同位置间切换；识别错误可能导致控制逻辑失效或接线错误。须按开关标识和图纸核对。"],
["S4","照明控制","detail","原教材 Chapter 5 · Lighting circuits","原理图和安装图的作用有什么区别？","原理图突出电气连接和工作逻辑；安装图突出设备在建筑中的位置及控制关联。实际施工需按图纸要求结合使用。"],
["S4","照明控制","detail","原教材 Chapter 5 · Lighting circuits","开关控制中性线而非有源线可能造成什么风险？","开关断开后灯具内部仍可能带有有源电位，维护时造成触电危险；回路极性和开关位置须按当地规则验证。"],
["S4","保护接地与极性","core","原教材 Chapter 5 · Earthing and polarity","neutral（中性线）与 protective earth（保护接地）的基本作用有何不同？","中性线在正常工作中承载负载回流；保护接地在正常状态下不应承担负载电流，故障时为保护动作提供路径。"],
["S4","保护接地与极性","core","原教材 Chapter 5 · Earthing and polarity","为什么不能在下游随意把中性线和保护接地短接？","会使正常电流流经保护导体/可触及金属部分，造成危险电位并干扰保护装置；连接点必须符合系统设计和规范。"],
["S4","保护接地与极性","detail","原教材 Chapter 5 · Earthing and polarity","什么是 circuit polarity（回路极性）？","确认有源、中性及开关/保护装置的位置关系正确，确保断开装置切断规定的导体并避免外露部件带电。"],
["S4","保护接地与极性","detail","原教材 Chapter 5 · Earthing and polarity","安装图上画了接地符号，就能证明保护接地连续吗？","不能。图纸表示设计意图；完成后仍需按规定检查实际导体连接和连续性，并记录结果。"],
["S4","建筑施工协调","core","原教材 Chapter 5 · Building plans","建筑施工阶段顺序为什么对电气施工有帮助？","可判断何时需预埋、穿梁/墙、布管、安装设备和封闭表面，减少错过工序或破坏已完成工程。"],
["S4","建筑施工协调","detail","原教材 Chapter 5 · Building plans","钻穿木结构前为什么先检查图纸和结构位置？","孔洞可能削弱结构构件，也可能碰到其他服务；尺寸、位置及允许范围必须按图纸和适用结构要求确认。"],
["S4","建筑施工协调","detail","原教材 Chapter 5 · Building plans","在砖饰面/空腔墙中规划进线时要考虑什么？","墙体构造层次、排水/防潮、机械保护和规定入口位置；依课程图例、项目图纸及主管要求复核，不能仅凭经验开孔。"],
["S4","图纸复核","detail","原教材 Chapter 5 · Drawing coordination","发现现场与图纸不一致时，正确的学习与施工处理是什么？","暂停受影响部分，记录差异并向设计/主管人员澄清；不得自行把图纸虚线或推测当作批准的接线方案。"],
["S4","图纸复核","detail","原教材 Chapter 5 · Drawing coordination","为什么每次施工前要确认图纸版本和修订号？","避免依据过期布局、负载或设备规格施工；现场应使用当前批准版本并识别变更。"],
["S4","图纸与比例","detail","原教材 Chapter 5 · Drawings","比例尺图纸中标注尺寸与实测尺寸冲突时优先信什么？","先核对图纸说明；通常标注尺寸优先于按比例量取的尺寸，并应向设计方澄清冲突。"],
["S4","图纸与比例","detail","原教材 Chapter 5 · Drawings","图纸坐标网格/字母数字索引有什么用途？","用行列坐标快速定位图纸中的符号或设备，便于查表、沟通位置和交叉引用。"],
["S4","符号与布置","detail","原教材 Chapter 5 · Symbols","图例（legend）在读图时解决什么问题？","解释图中符号、线型、缩写和标识含义；不同项目可能有项目特定符号，不能只按记忆猜测。"],
["S4","符号与布置","core","原教材 Chapter 5 · Schedules","设备 schedule 为什么不能被图上的单个符号替代？","符号往往只表达类别或位置；schedule 补充编号对应的型号、规格或设备说明。"],
["S4","照明控制","detail","原教材 Chapter 5 · Lighting circuits","同一灯具在平面图上靠近两个开关符号，就能判断它是双控吗？","不能仅凭位置判断；要看控制虚线、回路图、符号和图例，确认两个控制点是否关联同一灯具。"],
["S4","照明控制","detail","原教材 Chapter 5 · Lighting circuits","照明安装图中的 switch wire 代表什么逻辑？","表示开关控制后的有源路径/控制关联；实际导体颜色、芯线用途和端子必须由图纸及规范确认。"],
["S4","保护接地与极性","detail","原教材 Chapter 5 · Earthing","保护接地连续性为什么需要实测而不是只做目视检查？","隐藏连接可能松脱、腐蚀或断开；目视无法证明低阻抗保护路径连续，需按规定测试。"],
["S4","建筑施工协调","detail","原教材 Chapter 5 · Construction sequence","setting out（施工放样）在建筑电气工程中是什么意思？","把建筑/电气图纸上的位置和尺寸转移到现场，标出设备、路线或开孔位置，以便协调施工。"],
["S4","建筑施工协调","detail","原教材 Chapter 5 · Construction sequence","为什么电气布线需要与其他服务进行协调？","减少结构冲突、交叉干涉、维护困难和后续返工，并确保各系统留有合理空间。"],
["S4","图纸复核","detail","原教材 Chapter 5 · Drawings","施工中发现图纸标注缺失时应怎么做？","记录缺项并向主管/设计人员请求澄清；未经批准不自行补设设备额定值或回路连接。"],
["S5","控制回路基础","core","S5课程材料 · Control circuits","control circuit（控制回路）与 power circuit（动力回路）关注点有何不同？","控制回路处理命令、逻辑和线圈等控制元件；动力回路向负载传送工作电能。二者需按图纸区分和协调。"],
["S5","控制回路基础","core","S5课程材料 · Control circuits","继电器/接触器线圈通电后通常发生什么？","线圈产生磁场，驱动衔铁动作，使相关触点改变状态；断电后触点按机构设计复位。"],
["S5","控制回路基础","detail","S5课程材料 · Control circuits","为什么控制回路图要先识别电源、保护和回路路径？","可从供电端沿逻辑追踪到线圈/负载，再回到返回端；便于检查保护、互锁和故障区段。"],
["S5","控制回路基础","detail","S5课程材料 · Control circuits","控制回路中熔断器/断路保护的主要目的是什么？","保护控制线路及元件免受规定范围内的过电流影响；额定值必须与设计、导线和设备协调。"],
["S5","继电器与触点","core","S5课程材料 · Relay contacts","常开触点（NO）在未励磁时是什么状态？","未励磁时触点断开；线圈/机构动作后按继电器结构闭合。"],
["S5","继电器与触点","core","S5课程材料 · Relay contacts","常闭触点（NC）在未励磁时是什么状态？","未励磁时触点闭合；线圈/机构动作后按继电器结构断开。"],
["S5","继电器与触点","detail","S5课程材料 · Relay contacts","继电器的 coil 与 contacts 如何实现电气控制？","控制电流使线圈产生磁力，线圈动作再改变触点状态；触点用于切换另一回路，具体隔离/额定能力看器件规格。"],
["S5","继电器与触点","detail","S5课程材料 · Relay contacts","继电器触点图应按什么状态绘制/识读？","通常以线圈未励磁的正常状态为基准识读；查看图例和器件标号确认。"],
["S5","接触器","core","S5课程材料 · Contactors","接触器主触点主要承担什么任务？","切换主电路负载电流；额定工作类别、电流和电压需匹配负载及应用。"],
["S5","接触器","core","S5课程材料 · Contactors","接触器辅助触点常用于什么？","状态反馈、控制逻辑、自保持和电气互锁等；不能未经核对就把辅助触点当作主触点使用。"],
["S5","接触器","detail","S5课程材料 · Contactors","接触器线圈电压为什么必须核对铭牌？","线圈额定电压/频率不匹配可能导致不动作、过热或损坏；要与控制电源及图纸一致。"],
["S5","接触器","detail","S5课程材料 · Contactors","接触器吸合后出现抖动，可能提示什么检查方向？","控制电压不稳、线圈/磁路问题、接线松动或机构污染磨损等；断电隔离后由合格人员按程序检查，不带电触摸。"],
["S5","自保持与互锁","core","S5课程材料 · Latching","自保持（seal-in / latching）回路的基本作用是什么？","启动命令短暂出现后，接触器辅助常开触点并联维持线圈供电，直到停止命令或保护动作打断回路。"],
["S5","自保持与互锁","detail","S5课程材料 · Latching","停止按钮在典型自保持回路中常使用哪种触点逻辑？","通常使用常闭控制触点，使按下停止按钮时控制回路断开；以实际电路图和器件标识为准。"],
["S5","自保持与互锁","core","S5课程材料 · Interlocking","电气互锁的目标是什么？","阻止互相冲突的两个控制状态同时成立，例如正转和反转接触器同时吸合。"],
["S5","自保持与互锁","detail","S5课程材料 · Interlocking","正反转接触器为何常同时采用电气和机械互锁？","电气互锁利用辅助触点切断对方线圈命令；机械互锁阻止两套机构同时闭合，形成额外防护层。具体配置遵从设计。"],
["S5","故障诊断","core","S5课程材料 · Troubleshooting","控制回路不动作时，按逻辑如何缩小检查范围？","先确认故障现象和安全状态，再按图沿控制电源、保护、命令触点、互锁、线圈和返回路径逐段检查并记录。"],
["S5","故障诊断","detail","S5课程材料 · Troubleshooting","测量线圈电阻前必须满足什么安全前提？","按程序隔离并验证无电，必要时断开一端避免并联路径影响读数；只由受训/授权人员操作。"],
["S5","故障诊断","detail","S5课程材料 · Troubleshooting","线圈有命令但接触器不吸合，哪些类别的原因值得区分？","线圈供电/额定不匹配、线圈开路或损坏、机构卡滞、控制回路压降或互锁条件未满足。先依据图纸和测量证据判断。"],
["S5","控制回路基础","detail","S5课程材料 · Control circuits","控制回路中的 stop/start 按钮一般分别承担什么逻辑？","Start 提供启动命令，Stop 中断保持/线圈路径；触点常态要按图纸和按钮标识确认。"],
["S5","继电器与触点","detail","S5课程材料 · Relay contacts","继电器线圈端子与触点端子是否电气上必然相连？","不一定。电磁继电器通常以线圈驱动触点机械动作，线圈回路和触点回路按器件绝缘/额定设计分开识别。"],
["S5","继电器与触点","detail","S5课程材料 · Relay contacts","触点的“常开/常闭”是相对于什么状态定义的？","相对于继电器线圈未励磁、机构处于正常静止状态定义。"],
["S5","接触器","detail","S5课程材料 · Contactors","接触器线圈失电时主触点通常如何变化？","在常见弹簧复位接触器中回到断开状态；具体器件结构和触点状态以铭牌/数据表为准。"],
["S5","接触器","detail","S5课程材料 · Contactors","为什么要确认接触器的使用类别/负载类型？","电机、电阻和其他负载的开断应力不同；选错类别会加速触点磨损或引发故障。"],
["S5","自保持与互锁","detail","S5课程材料 · Latching","在典型自保持回路中，按下启动后松开按钮为何线圈仍能保持？","接触器吸合后，其辅助常开触点闭合并旁路启动按钮，维持线圈回路；停止或保护动作会打断它。"],
["S5","自保持与互锁","detail","S5课程材料 · Interlocking","控制图中的互锁触点应串入哪个逻辑路径？","通常串入对方接触器的线圈控制路径，使一方动作时另一方线圈不能得电；以具体原理图为准。"],
["S5","故障诊断","detail","S5课程材料 · Troubleshooting","线圈电压正常但继电器不动作时应检查哪些方面？","线圈是否断路/损坏、机构是否卡滞、额定电压/频率是否匹配，以及测量参考点和仪表是否正确。"],
["S5","故障诊断","detail","S5课程材料 · Troubleshooting","接触器吸合但负载不运行，故障可能在哪些范围？","主触点或负载侧供电、过载保护、导线/端子、电机/负载本体及机械部分；按安全程序沿能量路径查证。"],
["S6","三相电机","core","S6课程材料 · Three-phase motors","三相交流电机定子绕组的三相电流产生什么结果？","产生旋转磁场；其旋转速度由电源频率和极数决定。"],
["S6","三相电机","core","S6课程材料 · Motor speed","同步转速公式是什么？","n_s = 120 f / P rpm，其中 f 为频率（Hz），P 为磁极总数。例：50 Hz、4 极电机同步转速为 1500 rpm。"],
["S6","三相电机","detail","S6课程材料 · Induction motors","感应电机转子为什么低于同步转速运行？","转子需与旋转磁场存在相对速度以感应电流和产生转矩；这一相对差异称为转差。"],
["S6","三相电机","core","S6课程材料 · Nameplate","电机铭牌上哪些信息对接线和保护选择很关键？","额定电压、电流、频率、功率、转速、接法/绕组数据、功率因数、效率及工作制等；以具体铭牌为准。"],
["S6","三相电机","detail","S6课程材料 · Star-delta","星形和三角形接法的绕组电压关系有何区别？","对同一线电压，星形每相绕组电压为线电压除以 √3；三角形每相承受线电压。必须按铭牌和电源匹配。"],
["S6","直接启动","core","S6课程材料 · DOL starter","DOL（直接启动）如何向电机供电？","接触器闭合后将电源直接接至电机端子，控制简单，但启动电流通常明显高于运行电流。"],
["S6","直接启动","detail","S6课程材料 · DOL starter","DOL 启动器的典型组成有哪些？","隔离/短路保护、接触器、过载保护和启停控制回路；具体组合及额定值按设计与产品标准核对。"],
["S6","直接启动","core","S6课程材料 · DOL starter","热过载继电器主要防护什么？","防止持续过载导致电机过热；它不等同于短路保护，需与上游短路保护器件协调。"],
["S6","直接启动","detail","S6课程材料 · DOL starter","过载继电器设定值应依据什么？","根据电机铭牌额定电流、接法、安装条件和保护器说明/适用规范设定，不凭电机功率猜值。"],
["S6","正反转","core","S6课程材料 · Reversing","三相感应电机如何改变旋转方向？","交换任意两相的相序可改变旋转磁场方向；必须先确保回路设计、联锁及安全条件正确。"],
["S6","正反转","core","S6课程材料 · Reversing","正反转控制为什么需要互锁？","避免正转与反转接触器同时闭合，否则可能造成相间短路或设备损坏。"],
["S6","正反转","detail","S6课程材料 · Reversing","正反转启动器的机械互锁和电气互锁各做什么？","机械互锁物理阻止对方接触器吸合；电气互锁用对方常闭辅助触点断开线圈控制路径。"],
["S6","保护与排故","core","S6课程材料 · Fault finding","电机过载跳闸后，为什么不能只把过载继电器复位继续运行？","跳闸是异常证据；须查明负载过重、缺相、低电压、通风受阻、轴承/机械卡滞或设定错误等原因。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","电机缺相可能出现哪些现象？","启动困难/不能启动、运行电流不平衡、转矩下降、过热或保护动作；诊断须用合适测量和安全程序。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","如何区分机械故障与电气故障的排查方向？","机械方向关注负载卡滞、轴承、对中和通风；电气方向关注供电相序/缺相、端子、绕组、保护和控制。先收集症状并按授权流程隔离。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","绕组绝缘测试前要注意什么？","电机必须隔离；断开可能受兆欧测试电压损坏的电子器件，并按制造商和测试程序选择电压与接线。"],
["S6","保护与排故","detail","S6课程材料 · Motor maintenance","电机启动后振动或异常噪声可能来自哪些类别？","安装松动、对中不良、轴承磨损、不平衡、负载问题或电磁异常；按症状逐项检查，不把单一原因当结论。"],
["S6","保护与排故","detail","S6课程材料 · Control circuits","故障修复后为什么要做功能验证？","确认保护、控制、旋向、启停和负载运行均符合设计，并记录测试结果；修好一个症状不等于系统已安全。"],
["S6","三相电机","core","S6课程材料 · Induction motors","转差率（slip）如何表示？","s = (n_s − n_r) / n_s；n_s 为同步转速，n_r 为转子实际转速。通常以比例或百分数表示。"],
["S6","三相电机","detail","S6课程材料 · Induction motors","负载增加时感应电机转差通常如何变化？","为产生更大转矩，转子转速通常略降、转差增大；实际范围依电机设计和负载条件。"],
["S6","三相电机","detail","S6课程材料 · Nameplate","铭牌上的 kW 通常表示什么？为什么计算电流时要确认？","可能标示电机额定机械输出功率；电源输入功率还要考虑效率，不能总把 kW 直接当电气输入功率。"],
["S6","直接启动","detail","S6课程材料 · DOL starter","直接启动对电源和机械负载的影响是什么？","启动电流较大，可能造成电压暂降和机械冲击；是否适用需按电机、负载和供电条件评估。"],
["S6","直接启动","detail","S6课程材料 · DOL starter","接触器与过载继电器各自控制什么？","接触器按控制命令接通/断开动力回路；过载继电器在检测到持续过载条件时使控制回路脱扣。"],
["S6","直接启动","detail","S6课程材料 · DOL starter","短路保护和电机过载保护为什么需要分别考虑？","短路故障电流和持续过载的热效应、时间特性不同；保护装置配合要满足两类故障要求。"],
["S6","正反转","detail","S6课程材料 · Reversing","改变三相电机相序前为什么先确认设备状态？","旋向改变可能危及泵、风机或传动机构；要确认负载要求、停止状态、隔离和互锁后再变更。"],
["S6","正反转","detail","S6课程材料 · Reversing","如果正反转回路的电气互锁失效，可能出现什么后果？","两个接触器可能同时吸合，导致相间短路或严重设备损坏；故障回路必须停用并修复。"],
["S6","保护与排故","core","S6课程材料 · Fault finding","电机不能启动，怎样分层检查比直接更换电机更有效？","先看供电与隔离状态，再查保护是否动作、控制命令/互锁、接触器和负载机械自由度，逐步收集证据。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","过载继电器反复动作时应检查哪些可能原因？","负载过大、机械卡滞、缺相/电压异常、冷却受阻、参数设定或器件故障；不能通过调高设定掩盖根因。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","电机运行电流不平衡可能指向什么？","电源相电压不平衡、接点/绕组问题、负载不均或测量误差；须在安全测量条件下核实各相数据。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","为什么要记录故障发生时的负载、温度和启动条件？","这些信息有助于区分持续过载、间歇故障、环境过热和启动问题，并支持复现与根因分析。"],
["S6","保护与排故","detail","S6课程材料 · Fault finding","更换电机后只看“转起来了”够不够？","不够。还要确认旋向、保护设定/协调、运行电流、机械负载、异常噪声/振动及完整测试记录。"],
["S7","导体基础","core","S7课程材料 · Conductors","导体的主要作用是什么？","为电流提供低阻抗路径；导体材料、截面积、长度、温度和敷设方式共同影响电气与热性能。"],
["S7","导体基础","detail","S7课程材料 · Conductors","实心导体与绞合导体的典型差别是什么？","实心导体由单根金属组成，较刚挺；绞合导体由多股细线组成，通常更柔韧。具体使用按电缆类型和端子要求。"],
["S7","导体基础","detail","S7课程材料 · Conductors","铜和铝导体端接时为什么不能不加区分地互换？","材料的导电率、热膨胀、氧化和端子兼容性不同；须用适用于该导体材料的接线端子和工艺。"],
["S7","导体基础","core","S7课程材料 · Conductors","导体绝缘层主要提供什么？","使带电导体与其他导体、设备和人员保持电气隔离，并满足规定的温度、环境和机械性能。"],
["S7","端接工艺","core","S7课程材料 · Terminations","压接端子的关键原则是什么？","端子型号、导体规格、模具和压接工具必须匹配；按制造商要求剥线、插入并压接，检查压痕与拉力/外观要求。"],
["S7","端接工艺","detail","S7课程材料 · Terminations","剥线时为什么不能划伤或切断导体股线？","有效截面积下降并形成应力集中，可能造成发热、断股或接头失效。"],
["S7","端接工艺","core","S7课程材料 · Terminations","螺钉端子拧紧后为什么要按规定扭矩执行？","扭矩过低会导致接触不良和发热；过高会损伤螺纹、导体或端子。使用器件规定的扭矩数据。"],
["S7","端接工艺","detail","S7课程材料 · Terminations","多股导体直接装入端子时要核对哪些兼容性？","端子是否允许该类绞线、是否需要套管/压接端头、允许截面积与剥线长度及紧固方式。不能让散股外露。"],
["S7","端接工艺","detail","S7课程材料 · Terminations","为什么不能把焊锡镀锡后的软导体直接压在不允许的螺钉端子下？","软焊料可能在压力和热循环下蠕变，使夹紧力下降并导致接触发热；遵从端子制造商对导体端接的要求。"],
["S7","电缆结构","core","S7课程材料 · Cables","电缆通常由哪些基本层次构成？","一个或多个导体、各自绝缘、可能的填充/内护层、外护套；按用途可能增加屏蔽、铠装或加强层。"],
["S7","电缆结构","detail","S7课程材料 · Cables","电缆外护套与导体绝缘的作用有何区别？","导体绝缘主要防止导体间/对地电气接触；外护套为电缆整体提供环境和机械保护，不可把外护套剥损当作无影响。"],
["S7","电缆结构","detail","S7课程材料 · Cables","为什么要按电缆印字/标识确认类型和规格？","外观相似的电缆可能在额定电压、导体材料、芯数、绝缘温度和环境适用性上不同。"],
["S7","线槽与保护","core","S7课程材料 · Trunking","线槽/电缆外壳对线路提供哪些帮助？","整理并支撑电缆、提供规定程度的机械保护、改善布线和维护；保护等级需按环境及产品设计确定。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","线槽内的毛刺或锐边会造成什么问题？","可能割伤导体绝缘，导致短路、接地故障或后续失效；切口应处理并使用合适护口/配件。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","金属线槽或金属外壳安装时要验证什么？","按系统设计和适用规范确认保护接地/电气连续性、连接处跨接要求及机械固定；不能只凭金属相接推定接地可靠。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","导体进入设备箱体时为什么要做应力释放/机械保护？","防止拉力、振动或锐边作用传递到端子和绝缘层，避免导体松脱或护套磨损。"],
["S7","导体基础","detail","S7课程材料 · Conductors","导体截面积增大通常会怎样影响电阻和载流能力？","在其他条件相同的情况下，截面积增大会降低电阻并通常提高散热载流能力；实际数值依材料和安装条件查表。"],
["S7","导体基础","detail","S7课程材料 · Conductors","电缆导体截面积与电缆外径是同一个尺寸吗？","不是。截面积描述金属导体截面；外径包括绝缘、护套等层次，不能用外径直接代替截面积规格。"],
["S7","导体基础","detail","S7课程材料 · Conductors","为什么高温电缆不等于可以任意提高工作温度？","允许温度受绝缘、端子、周围材料和安装条件中最严格的一项限制；按系统额定值整体校核。"],
["S7","端接工艺","detail","S7课程材料 · Terminations","压接完成后有哪些可见缺陷要留意？","压痕位置错误、模具/规格不符、股线外露或切断、端子变形/裂纹以及压接不完整；按工具和端子说明验收。"],
["S7","端接工艺","detail","S7课程材料 · Terminations","端子中的导体剥线长度为什么必须匹配？","太短会夹住绝缘层或导体啮合不足；太长会裸铜外露并可能触及邻近部件。按端子刻度/说明确定。"],
["S7","端接工艺","detail","S7课程材料 · Terminations","不同金属导体直接搭接可能产生什么问题？","氧化、热膨胀差异和电化学腐蚀可能造成接触电阻上升；需使用获准的兼容端子和表面处理方法。"],
["S7","电缆结构","detail","S7课程材料 · Cables","为什么电缆弯曲半径不能无限缩小？","过度弯折会损伤导体或绝缘、改变结构或影响屏蔽/护套；遵守电缆制造商最小弯曲半径。"],
["S7","电缆结构","detail","S7课程材料 · Cables","铠装层与屏蔽层的功能是否相同？","不相同。铠装通常提供机械保护；屏蔽层控制电磁干扰/电场等，具体结构和接地方式依电缆设计。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","电缆外壳进入配电箱时为什么要装护口或合适接头？","保护电缆免受锐边磨损，提供机械固定并维持系统的环境/防护要求。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","电缆桥架/梯架上的电缆如何避免局部受力？","按载荷要求设置支撑和固定，避免跨距过大、尖锐弯折、扎带过紧或集中堆载。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","布线外壳装满电缆后会带来哪些问题？","散热、穿线、维护和后续扩展困难；填充率、分隔和回路分组按标准与产品资料核验。"],
["S7","线槽与保护","detail","S7课程材料 · Trunking","导体标识在安装和检修中有什么价值？","便于区分回路、功能和端子，降低接错风险；标识应与图纸和现场记录一致。"],
["S8","验证顺序","core","S8课程材料 · Verification","电气安装为什么要在通电前完成规定的目视检查和断电测试？","可先发现错接、损伤、接地不连续和绝缘问题，避免在故障未识别时通电测试增加风险。"],
["S8","验证顺序","core","S8课程材料 · Verification","验证（verification）与功能测试有什么联系？","验证通过检查和测量证明安装符合设计/规定要求；功能测试确认设备按预期工作。两者不能互相完全替代。"],
["S8","验证顺序","detail","S8课程材料 · Verification","目视检查通常会关注哪些项目？","设备/导体损伤、正确规格、端接与紧固、极性、保护接地、标识、外壳完整、适用性和施工缺陷。具体清单按标准和项目确定。"],
["S8","连续性测试","core","S8课程材料 · Continuity","保护导体连续性测试要证明什么？","验证规定的保护接地路径从相关外露导电部分连续连接至接地端；记录测量结果并判定是否满足适用要求。"],
["S8","连续性测试","detail","S8课程材料 · Continuity","低电阻连续性测量为什么需要先补偿测试引线电阻？","引线电阻可能与被测回路电阻同量级；调零/补偿可减少引线对结果的影响。"],
["S8","绝缘测试","core","S8课程材料 · Insulation resistance","绝缘电阻测试主要寻找什么问题？","检查导体间或导体与地之间绝缘是否异常泄漏/损坏。测试电压、接线和合格限值须按回路、设备与现行标准确定。"],
["S8","绝缘测试","detail","S8课程材料 · Insulation resistance","绝缘电阻测试前为何要断开敏感电子设备？","测试仪会施加直流测试电压，可能损坏电子设备、浪涌保护器或控制元件；按制造商/标准要求隔离或采用适当测试方法。"],
["S8","绝缘测试","detail","S8课程材料 · Insulation resistance","为何不能把某一个绝缘电阻数字当作所有回路的通用合格线？","要求取决于电路电压、连接设备、测试方法、现行规范和制造商条件；应查当前适用标准，不从旧讲义孤立背数字。"],
["S8","极性与相序","core","S8课程材料 · Polarity","极性检查要确认哪些关键关系？","确认开关/保护装置位于规定的有源导体，插座和设备端子接线正确，且保护接地不被误作正常载流路径。"],
["S8","极性与相序","detail","S8课程材料 · Polarity","三相相序检查对电机为什么重要？","相序决定旋转磁场方向，接错可能令电机旋向与设备要求相反；按设备要求验证并记录。"],
["S8","RCD 测试","core","S8课程材料 · Protective devices","RCD 的测试按钮与仪器测试有什么区别？","按钮通常检查内部机构能否动作；专业测试仪可量测规定条件下的动作性能。依标准要求，两者不能简单互相替代。"],
["S8","记录与诊断","core","S8课程材料 · Test records","合格的测试记录应留下哪些可追溯信息？","被测回路/位置、测试项目与结果、仪器识别/状态、测试条件、日期及人员信息；按当前表格和法规填写。"],
["S8","记录与诊断","detail","S8课程材料 · Test records","记录观察到的缺陷时，为什么要写可观察事实？","清楚描述位置、状态和证据，便于风险评估与后续处理；不要把未验证的推测写成确定故障原因。"],
["S8","记录与诊断","core","S8课程材料 · Fault finding","半分割法如何缩小复杂回路的故障范围？","在系统中间选择有意义的测试点，根据结果判断故障在测试点前还是后，再重复缩小范围；测试点须安全且能区分两段。"],
["S8","记录与诊断","detail","S8课程材料 · Fault finding","故障排查为什么要先收集症状和画功能块？","把“发生了什么、何时发生、哪些部分仍正常”变成可检验假设，避免盲目拆装和重复测量。"],
["S8","记录与诊断","detail","S8课程材料 · Fault finding","修复后必须进行什么闭环检查？","按原故障现象复现/验证功能，重新完成受影响的安全检查和测试，更新记录并交接任何遗留问题。"],
["S8","验证顺序","detail","S8课程材料 · Verification","初始验证通常由哪些互补部分组成？","目视检查、规定的断电测试、适用的通电/功能测试，以及完整记录；项目清单依回路和现行标准。"],
["S8","连续性测试","detail","S8课程材料 · Continuity","测试导体连续性前为何要先确认回路已隔离？","避免测试仪接入带电回路造成触电、设备损坏或错误读数；先执行授权隔离和验证程序。"],
["S8","绝缘测试","detail","S8课程材料 · Insulation resistance","做绝缘测试后为什么有些回路还要放电？","被测电缆/设备可能储存测试电荷；按仪表和工作程序等待自动放电或安全放电并确认后再接触。"],
["S8","极性与相序","detail","S8课程材料 · Polarity","极性测试为什么要在适当条件下结合图纸判断？","单一电压读数可能无法识别所有接线错误；需理解预期回路、参考点和测试方法，并记录结果。"],
["S8","RCD 测试","detail","S8课程材料 · RCD testing","RCD 测试结果为什么要记录测试条件和仪器？","动作时间/电流结果受测试模式、相位角、仪表和安装条件影响；记录便于复核并与适用要求比较。"],
["S8","记录与诊断","detail","S8课程材料 · Fault finding","有电压读数是否就证明电路能正常带负载？","不一定。高阻连接或感应电压可能在空载测量时显示电压，但负载下异常；需用合适方法验证且遵守安全程序。"],
["S8","记录与诊断","detail","S8课程材料 · Fault finding","为什么故障排查一次只改变一个条件更可靠？","可把结果归因于具体变化，减少多个操作同时发生导致的混淆，并保留可重复的诊断记录。"],
["S8","记录与诊断","detail","S8课程材料 · Fault finding","故障修复后若读数恢复但保护器仍频繁动作，应如何判断？","故障未必根除；检查负载条件、间歇性故障和测试证据，不能把一次正常读数当作最终验证。"],
["S9","导管与外壳","core","S9课程材料 · Wiring enclosures","选择导管/线槽前要评估哪些现场条件？","室内外、紫外线、潮湿/化学腐蚀、机械冲击、温度、支撑结构、可维护性和适用的防护等级。"],
["S9","导管与外壳","detail","S9课程材料 · Wiring enclosures","为什么不能只按颜色判断导管的强度或适用环境？","颜色可能是产品识别信息，但等级和用途需由标识、认证及制造商规格确认；不同产品/地区未必采用相同颜色规则。"],
["S9","导管与外壳","core","S9课程材料 · Wiring enclosures","导管切口为什么要去毛刺并处理端口？","锐边会刮伤电缆绝缘或妨碍牵引；切后清理并使用需要的护口/接头。"],
["S9","导管与外壳","detail","S9课程材料 · PVC conduit","PVC 导管溶剂粘接为什么要清洁并按说明保持插接？","污染会削弱接合；插接深度、旋转、保持时间和固化时间因产品不同，按制造商说明执行。"],
["S9","导管与外壳","detail","S9课程材料 · Wiring enclosures","金属线槽连接处需要关注什么电气属性？","连接必须满足机械完整性与要求的接地连续性；是否需专用跨接件由系统设计和规则决定。"],
["S9","弯曲与支撑","core","S9课程材料 · Bending","导管弯曲时常见的质量缺陷是什么？","内侧起皱、外侧拉薄、压扁、折痕或半径过小；这些会削弱管体并增加穿线困难/电缆损伤风险。"],
["S9","弯曲与支撑","detail","S9课程材料 · Bending","为什么弯管时要保持截面圆整和连续弧度？","保证管内通道并避免局部受力和穿线阻力；按管材和管径使用匹配弯管器具。"],
["S9","弯曲与支撑","core","S9课程材料 · Supports","支撑点间距应依据什么确定？","导管/线槽型号、方向、载荷、温度、支撑基层及制造商和规范要求；不应将旧讲义中的一个间距套用所有情况。"],
["S9","弯曲与支撑","detail","S9课程材料 · Supports","为什么弯头、接线盒或接头附近需要检查支撑？","这些位置承受装配和拉线力，支撑不足可能使连接松脱、变形或把载荷传至端子。具体位置按系统要求确定。"],
["S9","路径规划","core","S9课程材料 · Route planning","布线路径规划要同时满足哪些目标？","安全、可施工、保护电缆、减少不必要弯头/接头、与其他服务协调，并便于检查和维护。"],
["S9","路径规划","detail","S9课程材料 · Route planning","施工前如何降低钻孔碰到隐藏服务的风险？","核对图纸与现场探测信息，确认许可和隔离要求，标记安全区域；有疑问先升级确认，不凭猜测钻孔。"],
["S9","路径规划","detail","S9课程材料 · Route planning","哪些情况可能需要考虑导管排水或封堵？","室外、温差凝露、潮湿或可能进水的路径；按系统设计和规范决定坡度、排水/密封，不能随意开孔破坏防护等级。"],
["S9","路径规划","detail","S9课程材料 · Route planning","留出布线外壳余量的价值是什么？","避免过度填充、降低牵引和散热困难，并为检查、维护或未来变更留出空间；允许填充率需按规则计算。"],
["S9","导管与外壳","detail","S9课程材料 · Conduit","light-duty、medium-duty、heavy-duty 等级如何正确选用？","根据产品标识及规定安装环境选择；等级名称不应脱离适用标准或产品说明单独推断。"],
["S9","导管与外壳","detail","S9课程材料 · Conduit","何时不能把普通 PVC 导管当作通用户外产品？","当其 UV、温度、冲击或化学兼容性不足时；查产品的环境标记和认证范围。"],
["S9","导管与外壳","detail","S9课程材料 · Conduit","使用溶剂水泥时为什么需要通风与皮肤防护？","溶剂可能挥发、刺激或具有可燃性，皮肤接触也可能有害；查 SDS，远离点火源并遵守 PPE 要求。"],
["S9","导管与外壳","detail","S9课程材料 · Wiring enclosures","电缆梯架/托盘与封闭导管的保护差异是什么？","梯架/托盘主要承托与整理，开放程度较高；封闭导管提供不同程度的机械和环境防护，必须按场所选用。"],
["S9","弯曲与支撑","detail","S9课程材料 · Bending","大半径弯曲为什么能帮助拉线？","减少电缆与管壁间的挤压和摩擦，并降低导体/绝缘承受的弯曲应力。"],
["S9","弯曲与支撑","detail","S9课程材料 · Bending","弯曲失败后看到凹陷或折痕，应该如何处理？","不要把缺陷当作合格管段继续使用；按产品/工程要求评估并更换或修正，确保内径和机械完整性。"],
["S9","路径规划","detail","S9课程材料 · Route planning","规划电缆拉线时为什么要考虑可达的拉线点？","过长路径或弯头过多会增加牵引力和损伤风险；在允许位置设置拉线/接线点便于施工与维护。"],
["S9","路径规划","detail","S9课程材料 · Route planning","路径经过潮湿、腐蚀或可能机械受损区域时要怎样重新评估？","检查外壳材料、防护等级、密封、支撑和附加机械保护是否与环境匹配，并核对产品使用边界。"],
["S9","路径规划","detail","S9课程材料 · Route planning","为什么穿墙/穿楼板的布线细节可能需要防火封堵？","开孔会破坏建筑的防火分隔；封堵系统需与穿越物、孔隙和耐火要求匹配，并由合格人员施工/记录。"],
["S10","负载与电流","core","S10课程材料 · Cable selection","设计电流 I_B 表示什么？","在预期正常运行条件下，回路预计承载的电流；由负载需求、供电参数及适用多样性规则确定。"],
["S10","负载与电流","core","S10课程材料 · Cable selection","保护装置额定电流 I_N 与设计电流 I_B 的基本关系是什么？","保护器额定值通常需不小于设计电流，并与导体允许载流量及故障保护条件协调；完整条件按适用标准和设计核算。"],
["S10","负载与电流","detail","S10课程材料 · Load calculations","单相纯电阻负载的电流如何估算？","I = P / V，前提是负载近似纯电阻且功率因数约为 1；一般交流负载还需考虑功率因数，电机还需考虑效率/启动特性。"],
["S10","负载与电流","detail","S10课程材料 · Load calculations","平衡三相负载的有功功率、电流、线电压关系是什么？","P = √3 × V_L × I_L × PF（忽略或另行处理效率时）；由此 I_L = P/(√3 V_L PF)。注意铭牌输入/输出功率定义。"],
["S10","电缆载流量","core","S10课程材料 · Cable selection","为什么电缆额定载流量不能只按导体截面积判断？","载流量还受敷设方式、绝缘材料/温度等级、环境温度、成束、隔热、导体材料和端接条件影响。"],
["S10","电缆载流量","detail","S10课程材料 · Cable selection","电缆校正系数的作用是什么？","将参考条件下的表列载流量调整到实际环境；常见因素包括环境温度、成束和隔热敷设。须按相应表格和条件应用。"],
["S10","电缆载流量","core","S10课程材料 · Cable selection","载流量选择为什么要查电缆标准表而不是只用通用经验？","相同截面积在不同电缆、敷设和环境下散热能力不同；查当前适用表格并应用校正系数才能得出可用载流量。"],
["S10","电压降","core","S10课程材料 · Voltage drop","电压降的基本物理关系是什么？","导体阻抗上产生电压损失；简单直流/电阻近似为 V_d = I × R。交流电缆需考虑阻抗及相制条件。"],
["S10","电压降","detail","S10课程材料 · Voltage drop","影响电缆电压降的主要因素有哪些？","负载电流、线路长度、导体截面积和材料、温度及交流线路的阻抗/功率因数。"],
["S10","电压降","core","S10课程材料 · Voltage drop","为什么要把上游各段压降累计起来？","终端电压受从电源点到负载的整条供电路径影响；只核算最后一段会低估总压降。"],
["S10","电压降","detail","S10课程材料 · Voltage drop","mV/A·m 法通常如何计算电压降？","按电缆表中与相制/功率因数对应的 mV/A·m 系数乘以电流和单程长度，再除以 1000 得伏特；核对表中系数定义。"],
["S10","电压降","detail","S10课程材料 · Voltage drop","为何不能把一种教材示例的固定百分比当作所有安装通用限值？","允许值受当前规范、供电条件、回路用途和设计要求影响；课程中的数字用于对应教材范围，项目要按现行规则确认。"],
["S10","保护协调","core","S10课程材料 · Protection coordination","电缆与保护装置协调的核心目的是什么？","在规定故障和过载条件下保护导体与设备，避免导体过热，同时保证保护装置能按要求切断故障。"],
["S10","保护协调","detail","S10课程材料 · Protection coordination","选择保护装置时为什么不仅看额定电流？","还要核对分断能力、故障回路条件、动作特性、负载启动电流、导体保护和上下级选择性等要求。"],
["S10","保护协调","detail","S10课程材料 · Protection coordination","RCD、过载保护与短路保护能否互相替代？","不能简单互换：它们针对的故障/危险不同；使用组合器件时也须确认各功能和额定值满足设计。"],
["S10","计算与查表","core","S10课程材料 · Design checks","电缆选型的学习顺序怎样组织才不容易漏项？","确定负载与 I_B，选择保护器并核对协调，依敷设条件查载流量并校正，再校验电压降及故障保护要求，最后记录假设与表格来源。"],
["S10","计算与查表","detail","S10课程材料 · Design checks","设计计算记录为什么要写明表格版本、安装假设和校正系数？","他人才能复核计算是否使用了正确条件；敷设方式或环境一变，原载流量/压降结论可能不再成立。"],
["S10","计算与查表","detail","S10课程材料 · Design checks","导体按载流量合格但电压降不合格时，常见设计调整方向是什么？","重新检查路径长度与数据假设，必要时增大截面积或调整供电/回路布局，再重新验证载流量、保护协调和故障条件。"],
["S10","负载与电流","detail","S10课程材料 · Load calculations","最大需求（maximum demand）为什么可能小于所有负载铭牌功率之和？","某些负载不太可能同时以最大值运行，设计规则可能允许按规定需求因子评估；系数必须查适用标准，不能自行估计。"],
["S10","负载与电流","detail","S10课程材料 · Load calculations","功率因数降低时，同一有功功率需要怎样变化的电流？","电压不变时，功率因数较低通常需要更大的电流才能传输相同有功功率；这会影响载流量和压降。"],
["S10","电缆载流量","detail","S10课程材料 · Cable selection","隔热材料包围电缆为什么会降低可用载流量？","隔热妨碍散热，使导体温升更高；需按标准表格和实际被隔热长度/方式确定校正。"],
["S10","电缆载流量","detail","S10课程材料 · Cable selection","多根回路成束敷设为什么常需降额？","相邻电缆彼此加热、散热条件变差，单根电缆可承载电流下降；按成束数量和布置查系数。"],
["S10","电压降","detail","S10课程材料 · Voltage drop","线路长度加倍、其他条件不变时，电阻性压降通常怎样变化？","在线性近似下电阻与长度成正比，压降也约成比例增加；实际交流电路还受电抗和功率因数影响。"],
["S10","电压降","detail","S10课程材料 · Voltage drop","为什么电压降计算要使用单程线路长度还是回路长度，必须先看表格定义？","有的系数已包含单相去回路径或相制换算；再乘二会造成重复计算，必须按数据表定义解释长度和系数。"],
["S10","保护协调","detail","S10课程材料 · Protection coordination","过载保护的基本任务是什么？","在导体或设备因过电流产生有害热效应前切断回路；器件特性需与导体和负载匹配。"],
["S10","保护协调","detail","S10课程材料 · Protection coordination","保护装置的分断能力要与什么匹配？","安装点可能出现的预期短路电流；分断能力不足时，器件可能无法安全切断故障。"],
["S10","保护协调","detail","S10课程材料 · Protection coordination","保护选择性（selectivity）希望实现什么结果？","故障时尽可能由靠近故障点的保护装置先动作，减少其他健康回路被切断；须查看器件配合数据和故障范围。"],
["S10","计算与查表","detail","S10课程材料 · Design checks","为什么电缆计算需要明确敷设方法？","不同敷设方式散热、载流能力和表格系数不同；未确定方法就选表会导致结果不可复核。"]
];
